// Personalized content for municipio pages (ES only, other locales use template)
// Each entry contains a rich, multi-paragraph description unique to the municipality

export const municipiosContent: Record<string, string> = {
  // === BARCELONA ===
  'igualada': 'Igualada, capital de la comarca de la Anoia, se encuentra clasificada en Zona II (exposición alta) al gas radón. Su ubicación en la depresión central catalana, sobre sustratos graníticos y sedimentarios, favorece la acumulación de radón en espacios cerrados. El Real Decreto 1029/2022 establece la obligatoriedad de realizar mediciones en centros de trabajo ubicados en esta zona de actuación prioritaria.\n\nLa actividad industrial histórica de Igualada, con numerosas naves y edificios comerciales, hace especialmente relevante la medición de radón en espacios laborales. ACM-2020 ofrece servicios profesionales de medición con detectores pasivos de larga duración, cumpliendo con los protocolos establecidos por el CSN (Consejo de Seguridad Nuclear).',

  'manresa': 'Manresa, capital del Bages, está clasificada como Zona II (exposición alta) al gas radón. La comarca del Bages se asienta sobre formaciones geológicas ricas en materiales graníticos y evaporíticos que favorecen la emanación natural de radón. Los niveles de concentración en esta zona pueden superar significativamente el nivel de referencia de 300 Bq/m3.\n\nComo centro urbano e industrial de referencia en la Catalunya central, Manresa cuenta con un importante parque de edificios residenciales y comerciales donde la medición de radón resulta prioritaria. ACM-2020 realiza mediciones profesionales de la concentración media anual de gas radón, siguiendo la metodología establecida por la normativa vigente.',

  'berga': 'Berga, capital del Berguedà, se sitúa en plena zona de actuación prioritaria Zona II (exposición alta) al gas radón. La geología del Berguedà, con predominio de materiales graníticos del Prepirineo catalán, genera condiciones propicias para la emanación de radón desde el subsuelo. Esta comarca presenta algunos de los niveles más elevados de toda Catalunya.\n\nLa tradición industrial textil del Berguedà ha dejado un patrimonio de edificios y naves que requieren evaluación frente al radón. Además, las viviendas de núcleo antiguo, con cimentaciones tradicionales y menor estanqueidad, son especialmente vulnerables. ACM-2020 ofrece soluciones integrales desde la medición hasta la implementación de sistemas de mitigación.',

  'vic': 'Vic, capital de la comarca de Osona, está clasificada en Zona II (exposición alta) al gas radón. La Plana de Vic, rodeada de formaciones montañosas, presenta una geología con sustratos arcillosos y graníticos que favorecen la concentración de radón. El clima continental de la zona, con inversiones térmicas frecuentes, puede agravar la acumulación del gas en interiores durante los meses fríos.\n\nComo centro de servicios y comercio de Osona, Vic cuenta con un tejido empresarial diverso que debe cumplir con las obligaciones del RD 1029/2022. ACM-2020 dispone de amplia experiencia en mediciones de radón tanto en edificios residenciales como en centros de trabajo, ofreciendo un servicio adaptado a las necesidades de cada cliente.',

  'terrassa': 'Terrassa, en la comarca del Vallès Occidental, se encuentra clasificada en Zona I (exposición media) al gas radón. Su proximidad a las formaciones montañosas de Sant Llorenç del Munt y la Serra de l\'Obac, con sustratos de conglomerados y calizas, genera niveles moderados de radón que requieren vigilancia preventiva.\n\nComo una de las ciudades más pobladas de Catalunya, Terrassa cuenta con un extenso parque inmobiliario e industrial donde la medición preventiva de radón es recomendable. ACM-2020 ofrece servicios de medición y asesoramiento para propietarios, empresas y administraciones que deseen verificar los niveles de radón en sus inmuebles.',

  'sabadell': 'Sabadell, ciudad del Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. La geología del Vallès, con depósitos cuaternarios sobre sustratos graníticos y metamórficos de la Serralada Prelitoral, genera niveles moderados de emanación de radón que hacen recomendable la medición preventiva en edificios.\n\nEl importante tejido industrial y comercial de Sabadell, junto con su densidad urbana, hace conveniente la verificación de niveles de radón en centros de trabajo y viviendas, especialmente en plantas bajas y sótanos. ACM-2020 realiza mediciones profesionales con detectores homologados, proporcionando informes detallados según la normativa vigente.',

  'sant-cugat-del-valles': 'Sant Cugat del Vallès se encuentra en Zona I (exposición media) al gas radón. Su ubicación en la vertiente sur de la Serra de Collserola, sobre materiales graníticos y pizarrosos del macizo paleozoico, favorece niveles moderados de radón que hacen aconsejable la realización de mediciones preventivas, especialmente en viviendas unifamiliares y edificios con sótano.\n\nACM-2020 ofrece servicios de medición de radón en Sant Cugat, con especial atención a urbanizaciones y viviendas aisladas que, por su contacto directo con el terreno, pueden presentar niveles superiores a los edificios plurifamiliares.',

  'la-garriga': 'La Garriga, en el Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Este municipio, conocido por sus aguas termales, se asienta sobre una falla geológica activa que facilita la ascensión de gases del subsuelo, incluido el radón. La presencia de aguas termales es un indicador directo de actividad geológica que favorece la emanación de radón.\n\nLa combinación de geología granítica, actividad termal y un núcleo urbano con edificaciones históricas hace de La Garriga un municipio donde la medición de radón es especialmente importante. ACM-2020 realiza mediciones profesionales tanto en viviendas como en establecimientos termales y centros de trabajo.\n\nLa Garriga limita con [Figaró-Montmany](/municipios/figaro-montmany), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles), municipios de actuación prioritaria, y por otro lado, [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles) (Zona 1), y también limita con Cànoves i Samalús, zona sin clasificar.',

  'caldes-de-montbui': 'Caldes de Montbui, en el Vallès Oriental, se sitúa en Zona II (exposición alta) al gas radón. Al igual que La Garriga, Caldes es conocida por sus aguas termales, lo que evidencia una geología activa con fracturas que facilitan la ascensión de radón desde las capas profundas del subsuelo. Las fuentes termales más calientes de la península ibérica se encuentran en este municipio.\n\nLa medición de radón en Caldes de Montbui es prioritaria tanto en viviendas como en los numerosos establecimientos vinculados al termalismo. ACM-2020 ofrece un servicio integral de medición y diagnóstico, con detectores pasivos de larga duración que proporcionan una lectura fiable de la concentración media anual.\n\nCaldes de Montbui limita con [Bigues i Riells](/municipios/bigues-i-riells) y [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana) (zonas de actuación prioritaria), Lliçà d\'Amunt, [Palau-solita i Plegamans](/municipios/palau-de-plegamans), [Sentmenat](/municipios/sentmenat), Sant Llorenç Savall y Sant Feliu de Codines (municipios en zona 1), y también limita con Gallifa, zona sin clasificar.',

  'sant-celoni': 'Sant Celoni, en el Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. Situado a los pies del Montseny, la geología granítica del macizo y los materiales metamórficos circundantes generan condiciones favorables para la emanación de radón. La proximidad del Parc Natural del Montseny, con sus formaciones rocosas antiguas, contribuye a los elevados niveles registrados.\n\nACM-2020 realiza mediciones de radón en Sant Celoni y municipios del entorno del Montseny, donde la combinación de altitud, geología granítica y clima húmedo puede generar concentraciones significativas en interiores.\n\nSant Celoni limita con los municipios de [Gualba](/municipios/gualba), Riells y Viabrea, Sant Feliu de Buixalleu, [Fogars de la Selva](/municipios/fogars-de-la-selva), [Tordera](/municipios/tordera), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Vallgorguina](/municipios/vallgorguina) y [Santa Maria de Palautordera](/municipios/santa-maria-de-palautordera), todos ellos zonas de actuación prioritaria, y por otro lado Campins y Fogars de Montclus, municipios declarados Zona 1.',

  'olesa-de-montserrat': 'Olesa de Montserrat, en el Baix Llobregat, se encuentra en Zona II (exposición alta) al gas radón. Su ubicación al pie de la montaña de Montserrat, con formaciones de conglomerados sobre base granítica, y la presencia de fallas geológicas en la zona, favorecen la emanación de radón desde el subsuelo.\n\nEl municipio combina un núcleo urbano histórico con zonas residenciales de nueva construcción. En ambos casos, la medición de radón es obligatoria en centros de trabajo según el RD 1029/2022. ACM-2020 ofrece servicios de medición profesional adaptados a cada tipo de edificación.',

  'esparreguera': 'Esparreguera, en el Baix Llobregat, está clasificada en Zona II (exposición alta) al gas radón. Situada entre las formaciones de Montserrat y la depresión del Llobregat, la geología del municipio incluye conglomerados, calizas y materiales graníticos que favorecen niveles elevados de radón en el subsuelo.\n\nLa actividad industrial y comercial de Esparreguera, junto con su crecimiento residencial, hacen necesaria la realización de mediciones de radón en centros de trabajo y viviendas. ACM-2020 dispone de los medios técnicos y la experiencia necesaria para realizar estas mediciones de acuerdo con la normativa vigente.',

  'solsona': 'Solsona, capital del Solsonès, está clasificada en Zona II (exposición alta) al gas radón. La geología del Solsonès, con predominio de materiales evaporíticos, calizas y sustratos graníticos del interior de Catalunya, genera condiciones propicias para niveles elevados de radón. La altitud del municipio y su clima continental favorecen además la acumulación del gas en interiores durante largos períodos.\n\nComo capital comarcal, Solsona concentra servicios, comercios y centros de trabajo que deben cumplir con la obligatoriedad de medición establecida por el RD 1029/2022. ACM-2020 ofrece servicios de medición y control de radón con experiencia acreditada en municipios de la Catalunya central.',

  'dosrius': 'Dosrius, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. A diferencia de la mayoría de municipios costeros del Maresme, Dosrius se sitúa en el interior, sobre formaciones graníticas del macizo del Montnegre-Corredor que generan niveles elevados de emanación de radón.\n\nLas viviendas unifamiliares y masias dispersas, muy habituales en Dosrius, presentan un mayor contacto con el terreno y son especialmente vulnerables a la infiltración de radón. ACM-2020 recomienda la medición preventiva en este tipo de construcciones y ofrece soluciones de mitigación en caso necesario.\n\nDosrius limita con [Llinars del Vallès](/municipios/llinars-del-valles), [Vilalba Sasserra](/municipios/vilalba-sasserra), [Vallgorguina](/municipios/vallgorguina), [Arenys de Munt](/municipios/arenys-de-munt), [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt), [Sant Andreu de Llavaneres](/municipios/sant-andreu-de-llavaneres), [Mataró](/municipios/mataro), [Argentona](/municipios/argentona) y [La Roca del Vallès](/municipios/la-roca-del-valles), todos ellos zonas de actuación prioritaria.',

  'matadepera': 'Matadepera, en el Vallès Occidental, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie del Parc Natural de Sant Llorenç del Munt, sobre formaciones de conglomerados y sustratos graníticos, genera niveles elevados de radón. El carácter residencial del municipio, con predominio de viviendas unifamiliares aisladas, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón especialmente orientados a viviendas unifamiliares y chalets, donde la superficie de contacto con el terreno es mayor y las concentraciones de radón pueden ser significativamente superiores a las de edificios plurifamiliares.',

  'barcelona': 'Barcelona, capital de Catalunya, se encuentra clasificada en zona baja de exposición al gas radón. Sin embargo, determinadas zonas del municipio, especialmente las colindantes con Collserola y las áreas sobre sustratos graníticos paleozoicos, pueden presentar niveles puntuales que aconsejan la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Barcelona tanto para particulares como para empresas y administraciones. Aunque el riesgo general es bajo, la verificación es recomendable en plantas bajas, sótanos y locales comerciales situados en zonas con geología favorable a la emanación de radón.',

  'badalona': 'Badalona, en la comarca del Barcelonès, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie de la Serra de Marina, con formaciones graníticas y metamórficas de la Serralada Litoral, genera niveles elevados de radón, especialmente en las zonas norte del municipio. El Real Decreto 1029/2022 establece la obligatoriedad de medir la concentración de radón en centros de trabajo situados en esta zona de actuación prioritaria.\n\nACM-2020 ofrece servicios profesionales de medición de radón en Badalona, con atención especial a las edificaciones situadas en las laderas de la Serra de Marina y en las zonas de contacto con el sustrato granítico. El servicio incluye la instalación de detectores pasivos de larga duración y la elaboración de informes técnicos conformes a la normativa vigente.',

  'mataro': 'Mataró, capital del Maresme, se encuentra clasificada en Zona I (exposición media) al gas radón. Su ubicación entre la franja costera y las formaciones graníticas de la Serralada Litoral genera niveles moderados de radón que hacen recomendable la medición preventiva, especialmente en edificios con sótano y en locales situados en plantas bajas en contacto con el terreno.\n\nACM-2020 realiza mediciones de radón en Mataró y el Maresme, proporcionando informes detallados según la normativa vigente. Para empresas con centros de trabajo en esta zona de actuación prioritaria, el servicio incluye asesoramiento sobre las obligaciones derivadas del RD 1029/2022.\n\nMataró limita con [Dosrius](/municipios/dosrius), [Cabrera de Mar](/municipios/cabrera-de-mar), [Sant Andreu de Llavaneres](/municipios/sant-andreu-de-llavaneres) y [Argentona](/municipios/argentona), todos ellos zonas de actuación prioritaria.',

  'argentona': 'Argentona, en la comarca del Maresme, se encuentra clasificada en Zona I (exposición media) al gas radón. Su ubicación en el interior del Maresme, sobre formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón que hacen recomendable la realización de mediciones, especialmente en viviendas unifamiliares y edificios con plantas bajas o sótanos en contacto con el terreno.\n\nACM-2020 recomienda la medición preventiva de radón en Argentona, particularmente en urbanizaciones y viviendas aisladas. El servicio incluye la instalación de detectores pasivos durante un período mínimo de tres meses para obtener una lectura fiable de la concentración media anual.\n\nArgentona limita con [Òrrius](/municipios/orrius), [Cabrils](/municipios/cabrils), [La Roca del Vallès](/municipios/la-roca-del-valles), [Dosrius](/municipios/dosrius), [Cabrera de Mar](/municipios/cabrera-de-mar) y [Mataró](/municipios/mataro), todos ellos zonas de actuación prioritaria.',

  // === GIRONA ===
  'girona': 'Girona, capital de provincia, está clasificada en Zona I (exposición media) al gas radón. Aunque la ciudad se sitúa en la depresión del Ter-Onyar con predominio de materiales sedimentarios, la proximidad de formaciones graníticas de las Gavarres y del macizo de les Guilleries genera niveles moderados de radón que aconsejan la medición preventiva en determinados edificios.\n\nComo capital de provincia con un importante parque de edificios históricos y centros de trabajo, Girona requiere especial atención en la medición de radón. ACM-2020 ofrece servicios adaptados tanto a edificios de nueva construcción como a inmuebles históricos del casco antiguo, donde las características constructivas pueden favorecer la acumulación de radón.',

  'olot': 'Olot, capital de la Garrotxa, se encuentra en Zona II (exposición alta) al gas radón. La geología volcánica de la Garrotxa es única en la península ibérica: los suelos volcánicos, porosos y permeables, permiten la circulación y emanación de radón con facilidad. La zona volcánica de la Garrotxa, con más de 40 conos volcánicos, genera condiciones geológicas excepcionales para la concentración de radón.\n\nEl casco urbano de Olot, construido directamente sobre materiales volcánicos, presenta un riesgo específico que hace imprescindible la medición de radón en viviendas y centros de trabajo. ACM-2020 cuenta con experiencia en mediciones en zonas volcánicas y ofrece soluciones de mitigación adaptadas a las particularidades geológicas de la Garrotxa.',

  'ripoll': 'Ripoll, capital del Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Situada en la confluencia de los ríos Ter y Freser, en pleno Prepirineo catalán, la geología granítica y metamórfica de la zona genera niveles elevados de emanación de radón. La altitud y el clima de montaña favorecen además períodos prolongados con ventanas cerradas, lo que incrementa la acumulación en interiores.\n\nRipoll, con su importante patrimonio arquitectónico románico y un núcleo urbano histórico, requiere especial atención en la medición de radón. ACM-2020 ofrece servicios profesionales de medición adaptados a edificios históricos y centros de trabajo del Ripollès.',

  'camprodon': 'Camprodon, en el Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Este municipio pirenaico, a más de 900 metros de altitud, se asienta sobre formaciones graníticas y metamórficas que generan niveles muy elevados de radón. El clima frío de montaña, con largos períodos de calefacción y ventilación reducida, agrava la concentración del gas en interiores.\n\nLas casas tradicionales de piedra de Camprodon, así como las segundas residencias de montaña, requieren medición de radón. ACM-2020 realiza mediciones en toda la comarca del Ripollès, con experiencia en edificaciones de montaña y conocimiento de las particularidades climáticas que afectan a la concentración de radón.',

  'puigcerda': 'Puigcerdà, capital de la Cerdanya, se encuentra en Zona II (exposición alta) al gas radón. La Cerdanya, un amplio valle pirenaico a más de 1.100 metros de altitud, presenta una geología granítica y metamórfica que genera niveles muy elevados de emanación de radón. El clima continental de montaña, con temperaturas extremas en invierno, implica largos períodos con ventilación reducida en interiores.\n\nComo centro turístico y de segunda residencia, Puigcerdà cuenta con un parque inmobiliario diverso que requiere evaluación frente al radón. ACM-2020 ofrece mediciones profesionales y asesoramiento tanto para viviendas permanentes como para residencias de temporada en la Cerdanya.',

  'santa-coloma-de-farners': 'Santa Coloma de Farners, capital de la Selva, está clasificada en Zona II (exposición alta) al gas radón. La comarca de la Selva, con predominio de terrenos graníticos de la depresión prelitoral, presenta niveles significativos de radón. Santa Coloma, conocida por sus aguas termales, evidencia una geología activa que favorece la emanación de gases del subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Santa Coloma de Farners y municipios de la Selva, con especial atención a edificios situados sobre sustratos graníticos y en zonas con actividad termal.',

  'arbucies': 'Arbúcies, en la comarca de la Selva, se encuentra en Zona II (exposición alta) al gas radón. Situada al pie del Montseny, sobre formaciones graníticas paleozoicas, Arbúcies presenta niveles muy elevados de radón. El macizo del Montseny, uno de los batolitos graníticos más importantes de Catalunya, genera condiciones geológicas muy favorables para la emanación de radón.\n\nLas viviendas y masias de Arbúcies, muchas de ellas construidas directamente sobre roca granítica, requieren medición prioritaria de radón. ACM-2020 cuenta con experiencia en mediciones en municipios del Montseny y ofrece soluciones de mitigación adaptadas a edificaciones rurales y de montaña.',

  'besalu': 'Besalú, en la Garrotxa, está clasificada en Zona II (exposición alta) al gas radón. Este municipio medieval, situado en la confluencia del Fluvià y el Capellades, se asienta sobre materiales calizos y volcánicos que favorecen la emanación de radón. La proximidad a la zona volcánica de la Garrotxa incrementa el potencial de concentración.\n\nEl casco histórico de Besalú, con sus edificaciones medievales de piedra, requiere especial atención en la medición de radón debido a las características constructivas de estos edificios. ACM-2020 ofrece servicios de medición profesional con experiencia en patrimonio arquitectónico histórico.',

  'sant-joan-de-les-abadesses': 'Sant Joan de les Abadesses, en el Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Situada en el valle del Ter, en pleno Prepirineo catalán, la geología granítica y metamórfica de la zona genera niveles elevados de radón. El municipio, a unos 770 metros de altitud, experimenta condiciones climáticas que favorecen la acumulación en interiores.\n\nACM-2020 realiza mediciones de radón en Sant Joan de les Abadesses y el Ripollès, proporcionando informes detallados y asesoramiento sobre medidas de mitigación cuando los niveles superan el umbral de referencia de 300 Bq/m3.',

  'banyoles': 'Banyoles, capital del Pla de l\'Estany, está clasificada en Zona I (exposición media) al gas radón. La cuenca lacustre de Banyoles, con su complejo sistema hidrogeológico y los sustratos calizos y travertínicos, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Banyoles, con especial atención a edificios situados en las proximidades del lago y sobre formaciones calcáreas, donde la permeabilidad del terreno puede facilitar la migración de radón hacia el interior de los edificios.',

  'figueres': 'Figueres, capital del Alt Empordà, se encuentra clasificada en Zona I (exposición media) al gas radón. La llanura empordanesa, con depósitos aluviales sobre sustratos graníticos, presenta niveles moderados de radón. Las zonas norte del municipio, más próximas a las estribaciones pirenaicas, pueden registrar niveles superiores.\n\nComo capital comarcal con un importante sector de servicios y comercio, Figueres debe prestar atención a la medición de radón en centros de trabajo. ACM-2020 proporciona servicios de medición profesional con detección pasiva de larga duración conforme a la normativa vigente.',

  'sils': 'Sils, en la comarca de la Selva, está clasificada en Zona II (exposición alta) al gas radón. La geología granítica de la depresión prelitoral en la que se ubica Sils genera condiciones propicias para la emanación de radón. Los sustratos de arenas y gravas sobre base granítica permiten la migración del gas hacia la superficie con relativa facilidad.\n\nACM-2020 recomienda la medición de radón en viviendas y centros de trabajo de Sils, especialmente en edificaciones con plantas bajas en contacto directo con el terreno. El servicio incluye la instalación de detectores pasivos y la elaboración de informes técnicos conformes al RD 1029/2022.',

  'espolla': 'Espolla, en el Alt Empordà, está clasificada en Zona II (exposición alta) al gas radón. Este municipio de la sierra de la Albera, en la frontera con Francia, se asienta sobre formaciones graníticas y metamórficas del extremo oriental de los Pirineos que generan niveles muy elevados de radón.\n\nLa medición de radón en Espolla es obligatoria en centros de trabajo según el RD 1029/2022. ACM-2020 ofrece servicios de medición profesional en municipios del Alt Empordà, con experiencia en zonas de geología granítica pirenaica.',

  'alp': 'Alp, en la comarca de la Cerdanya, se encuentra en Zona II (exposición alta) al gas radón. Situado a más de 1.100 metros de altitud junto a la estación de esquí de la Masella, Alp se asienta sobre formaciones graníticas pirenaicas que generan niveles muy elevados de radón. El clima frío de montaña implica largos períodos de calefacción con ventilación reducida.\n\nACM-2020 realiza mediciones de radón en Alp y la Cerdanya, con atención especial a residencias de montaña y segundas viviendas donde la ventilación puede ser insuficiente durante períodos prolongados.',

  'llanars': 'Llanars, en el Ripollès, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico del valle de Camprodon, a más de 1.000 metros de altitud, se asienta sobre materiales graníticos que generan niveles elevados de emanación de radón. Su proximidad al macizo de la Comanegra refuerza el potencial de concentración.\n\nACM-2020 ofrece servicios de medición de radón en Llanars y el alto Ripollès, con experiencia en edificaciones de montaña y conocimiento de las condiciones climáticas que afectan a la concentración de radón en interiores.',

  'ger': 'Ger, en la Cerdanya, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico, situado a más de 1.100 metros de altitud, se asienta sobre formaciones graníticas que generan niveles muy elevados de radón. La Cerdanya es una de las comarcas con mayor concentración de radón de toda Catalunya.\n\nACM-2020 realiza mediciones profesionales de radón en Ger y la Cerdanya, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación en caso de superar los niveles de referencia establecidos por la normativa.',

  'cadaques': 'Cadaqués, en el Alt Empordà, está clasificado en Zona II (exposición alta) al gas radón. Situado en la península del Cap de Creus, la geología metamórfica y granítica de esta zona, una de las formaciones rocosas más antiguas de Catalunya, genera niveles elevados de radón. Las casas tradicionales de piedra y el núcleo histórico son especialmente vulnerables.\n\nACM-2020 ofrece servicios de medición de radón en Cadaqués, con atención a las particularidades constructivas de los edificios del casco antiguo y las viviendas situadas sobre el sustrato rocoso del Cap de Creus.',

  'portbou': 'Portbou, en el Alt Empordà, se encuentra en Zona II (exposición alta) al gas radón. Este municipio fronterizo, encajado entre las estribaciones orientales de los Pirineos y el Mediterráneo, se asienta sobre formaciones metamórficas y esquistos que favorecen la emanación de radón. La geología de pizarras y esquistos de la sierra de la Albera genera niveles significativos.\n\nACM-2020 realiza mediciones de radón en Portbou y municipios del extremo norte del Alt Empordà, donde la geología pirenaica genera condiciones favorables para la concentración de radón en interiores.',

  'llança': 'Llança, en el Alt Empordà, está clasificada en Zona II (exposición alta) al gas radón. La geología del municipio, con formaciones metamórficas y graníticas de las estribaciones orientales de los Pirineos, genera niveles elevados de radón. La proximidad al Cap de Creus, con sus formaciones rocosas antiguas, refuerza el potencial de emanación.\n\nACM-2020 ofrece servicios de medición de radón en Llança, tanto para viviendas como para los numerosos establecimientos turísticos y de restauración del municipio, donde la medición es obligatoria en centros de trabajo según el RD 1029/2022.',

  'amer': 'Amer, en la comarca de la Selva, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle medio del Ter, sobre sustratos graníticos del macizo de les Guilleries, Amer presenta niveles elevados de radón. La confluencia geológica entre la Selva y la Garrotxa genera condiciones especialmente favorables para la emanación.\n\nACM-2020 realiza mediciones profesionales de radón en Amer, con experiencia en municipios de la transición entre la Selva y las Guilleries, donde la geología granítica genera algunos de los niveles más elevados de la provincia de Girona.',

  'angles': 'Anglès, en la comarca de la Selva, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en el valle del río Onyar, sobre formaciones graníticas que generan niveles significativos de radón. La proximidad al macizo de les Guilleries y la Selva interior favorece la concentración del gas en el subsuelo.\n\nACM-2020 ofrece servicios de medición y control de radón en Anglès, con especial atención a las zonas residenciales situadas sobre sustratos graníticos. La medición con detectores pasivos de larga duración permite obtener una lectura fiable de la exposición real.',

  'osor': 'Osor, en la comarca de la Selva, se encuentra en Zona II (exposición alta) al gas radón. Este pequeño municipio del valle de les Guilleries se asienta directamente sobre el batolito granítico de les Guilleries, una de las formaciones graníticas más extensas de Catalunya, lo que genera niveles muy elevados de radón.\n\nLa medición de radón en Osor resulta prioritaria debido a la geología granítica del municipio. ACM-2020 cuenta con experiencia en mediciones en municipios rurales de les Guilleries y ofrece soluciones adaptadas a edificaciones tradicionales de piedra.',

  // === LLEIDA ===
  'la-seu-durgell': 'La Seu d\'Urgell, capital del Alt Urgell, está clasificada en Zona II (exposición alta) al gas radón. Situada en la confluencia del Segre y el Valira, en pleno Prepirineo leridano, la geología granítica y metamórfica de la zona genera niveles elevados de radón. La altitud del municipio, superior a 700 metros, implica condiciones climáticas que favorecen la acumulación en interiores.\n\nComo capital comarcal y centro de servicios del Pirineo leridano, La Seu d\'Urgell cuenta con un importante parque de edificios públicos, comerciales y residenciales que deben verificar sus niveles de radón. ACM-2020 ofrece servicios de medición profesional en todo el Alt Urgell.',

  'tremp': 'Tremp, capital del Pallars Jussa, se encuentra en Zona II (exposición alta) al gas radón. La geología del Pallars Jussa, con formaciones calizas, margas y sustratos graníticos del Prepirineo, genera niveles elevados de radón. La Conca de Tremp, una depresión estructural rodeada de sierras, puede favorecer la acumulación de radón en determinadas condiciones atmosféricas.\n\nACM-2020 realiza mediciones de radón en Tremp y el Pallars Jussa, ofreciendo un servicio profesional adaptado a las condiciones específicas del Prepirineo leridano. La medición es obligatoria en centros de trabajo ubicados en esta zona de actuación prioritaria.',

  'sort': 'Sort, capital del Pallars Sobira, está clasificada en Zona II (exposición alta) al gas radón. Situado en el Pirineo leridano a más de 700 metros de altitud, Sort se asienta sobre formaciones graníticas y metamórficas que generan niveles muy elevados de radón. El clima de montaña, con inviernos largos y fríos, favorece la acumulación del gas en interiores durante meses.\n\nACM-2020 ofrece servicios de medición de radón en Sort y el Pallars Sobira, con experiencia en municipios de alta montaña donde las condiciones climáticas y geológicas hacen especialmente importante la verificación de los niveles de radón.',

  'vielha': 'Vielha, capital de la Val d\'Aran, se encuentra en Zona II (exposición alta) al gas radón. La Val d\'Aran, único valle atlántico de Catalunya, presenta una geología granítica y metamórfica de alta montaña que genera niveles muy elevados de radón. La altitud, superior a 1.000 metros, y el clima atlántico con precipitaciones abundantes, crean condiciones específicas para la concentración de radón.\n\nComo centro turístico de primer nivel, Vielha cuenta con un importante parque hotelero y de servicios donde la medición de radón es obligatoria. ACM-2020 realiza mediciones profesionales en la Val d\'Aran, con conocimiento de las particularidades geológicas y climáticas de este territorio singular.',

  'el-pont-de-suert': 'El Pont de Suert, en la Alta Ribagorça, está clasificado en Zona II (exposición alta) al gas radón. Situado en el Pirineo central leridano, la geología granítica y metamórfica de la zona genera niveles muy elevados de radón. La confluencia de los ríos Noguera Ribagorçana y el Noguera de Tor crea un entorno geológico complejo favorable a la emanación.\n\nACM-2020 ofrece servicios de medición de radón en El Pont de Suert y la Alta Ribagorça, con experiencia en municipios de montaña del Pirineo leridano.',

  'solsona-lleida': 'Solsona, en la comarca del Solsonès (provincia de Lleida), está clasificada en Zona II (exposición alta) al gas radón. La geología del Solsonès, con evaporitas, calizas y sustratos graníticos, genera condiciones muy favorables para la emanación de radón. El carácter continental del clima, con amplitudes térmicas importantes, puede agravar la acumulación en interiores.\n\nACM-2020 realiza mediciones profesionales de radón en Solsona, con experiencia en la Catalunya central. El servicio incluye la instalación de detectores pasivos, la recogida tras el período de exposición y la elaboración de informes técnicos.',

  'ponts': 'Ponts, en la comarca de la Noguera, está clasificado en Zona II (exposición alta) al gas radón. Situado en la transición entre la depresión central y el Prepirineo, Ponts se asienta sobre formaciones geológicas mixtas que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Ponts y la comarca de la Noguera, proporcionando informes técnicos conformes al RD 1029/2022 y asesoramiento sobre medidas de mitigación.',

  'alins': 'Alins, en el Pallars Sobira, está clasificado en Zona II (exposición alta) al gas radón. Este municipio de alta montaña, situado en la Vall Ferrera a más de 1.000 metros de altitud, se asienta sobre formaciones graníticas y metamórficas del Pirineo axial que generan niveles muy elevados de radón. Las viviendas de piedra tradicionales y las condiciones climáticas extremas de invierno favorecen la concentración.\n\nACM-2020 realiza mediciones de radón en Alins y el alto Pallars, con experiencia en municipios de alta montaña donde las particularidades constructivas y climáticas requieren un enfoque especializado.',

  'vilaller': 'Vilaller, en la Alta Ribagorça, está clasificado en Zona II (exposición alta) al gas radón. Situado en el Pirineo central leridano, la geología granítica y termal de la zona genera niveles muy elevados de radón. La presencia de aguas termales en las proximidades de Vilaller evidencia una actividad geológica que favorece la emanación de gases del subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Vilaller y la Alta Ribagorça, con atención a las edificaciones tradicionales de piedra y a los centros de trabajo del municipio.',

  // === TARRAGONA ===
  'montblanc': 'Montblanc, capital de la Conca de Barbera, se encuentra en Zona II (exposición alta) al gas radón. La geología de la Conca de Barbera, con calizas, conglomerados y sustratos graníticos del macizo de Prades, genera niveles elevados de radón. El casco histórico medieval de Montblanc, con sus murallas y edificaciones de piedra, es especialmente relevante por las características constructivas que favorecen la infiltración de radón.\n\nACM-2020 realiza mediciones de radón en Montblanc y la Conca de Barbera, con especial atención al patrimonio arquitectónico histórico y a los centros de trabajo del municipio.',

  'falset': 'Falset, capital del Priorat, está clasificada en Zona II (exposición alta) al gas radón. La geología del Priorat, con sus características pizarras llicorella sobre base granítica, genera niveles elevados de radón. Los suelos de pizarra, porosos y fracturados, facilitan la migración del gas hacia la superficie.\n\nEl Priorat, reconocido internacionalmente por su viticultura, cuenta también con bodegas y espacios de trabajo subterráneos donde la medición de radón es especialmente importante. ACM-2020 ofrece servicios de medición profesional en Falset y toda la comarca del Priorat.',

  'valls': 'Valls, capital del Alt Camp, está clasificada en Zona I (exposición media) al gas radón. La transición geológica entre la llanura del Camp de Tarragona y las formaciones montañosas del interior genera niveles moderados de radón que hacen recomendable la medición preventiva en edificios.\n\nACM-2020 ofrece servicios de medición de radón en Valls, con atención a centros de trabajo y viviendas donde la verificación de niveles es recomendable según la normativa vigente.',

  'gandesa': 'Gandesa, capital de la Terra Alta, se encuentra clasificada en Zona I (exposición media) al gas radón. La geología de la Terra Alta, con calizas y materiales sedimentarios sobre sustratos más antiguos, genera niveles moderados de radón. El clima continental extremo de la comarca implica largos períodos con ventilación reducida en interiores.\n\nACM-2020 realiza mediciones de radón en Gandesa y la Terra Alta, proporcionando un servicio profesional adaptado a las necesidades de particulares y empresas de la comarca.',

  'tortosa': 'Tortosa, capital del Baix Ebre, está clasificada en Zona I (exposición media) al gas radón. Situada en el tramo final del Ebro, la geología del municipio combina depósitos aluviales con formaciones calizas y margosas que generan niveles moderados de radón. Las zonas elevadas del municipio, próximas a los Ports, pueden presentar niveles superiores.\n\nACM-2020 ofrece servicios de medición de radón en Tortosa y el Baix Ebre, con atención a las particularidades geológicas de la cuenca del Ebro y las sierras circundantes.',

  'botarell': 'Botarell, en la comarca del Baix Camp, está clasificado en Zona II (exposición alta) al gas radón. Este municipio del interior del Camp de Tarragona, próximo a las sierras de Prades y la Mussara, se asienta sobre formaciones geológicas que generan niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Botarell, con atención a viviendas y centros de trabajo donde la medición es obligatoria según el RD 1029/2022.',

  'aleixar': 'L\'Aleixar, en la comarca del Baix Camp, se encuentra clasificado en Zona II (exposición alta) al gas radón. Su ubicación al pie de la sierra de la Mussara, sobre materiales graníticos y metamórficos, genera condiciones favorables para niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición profesional de radón en L\'Aleixar y municipios del interior del Baix Camp, cumpliendo con los protocolos establecidos por el Consejo de Seguridad Nuclear.',

  'riudecanyes': 'Riudecanyes, en la comarca del Baix Camp, está clasificado en Zona II (exposición alta) al gas radón. Situado en las estribaciones de las montañas de Prades, la geología del municipio, con materiales graníticos y metamórficos, genera niveles elevados de emanación de radón.\n\nACM-2020 realiza mediciones de radón en Riudecanyes, proporcionando informes técnicos conformes a la normativa vigente y asesoramiento sobre medidas de mitigación cuando los niveles superan el umbral de referencia.',

  'riudecols': 'Riudecols, en la comarca del Baix Camp, está clasificado en Zona II (exposición alta) al gas radón. La geología del municipio, en la transición entre el Camp de Tarragona y las sierras interiores, genera niveles elevados de radón que hacen obligatoria la medición en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Riudecols y el Baix Camp interior, con experiencia en la zona y conocimiento de las particularidades geológicas locales.',

  'almoster': 'Almoster, en la comarca del Baix Camp, se encuentra clasificado en Zona II (exposición alta) al gas radón. Este municipio del interior del Camp, próximo a las formaciones montañosas de Prades, se asienta sobre sustratos que favorecen la emanación de radón.\n\nLa medición de radón en Almoster es obligatoria en centros de trabajo subterráneos y en lugares donde se procese agua de origen subterráneo, según el RD 1029/2022. ACM-2020 ofrece servicios profesionales de medición y diagnóstico.',

  'alforja': 'Alforja, en la comarca del Baix Camp, está clasificada en Zona II (exposición alta) al gas radón. Situado en las estribaciones de las montañas de Prades, la geología granítica y metamórfica del municipio genera niveles significativos de radón. La sierra de la Mussara, próxima a Alforja, es una de las zonas con mayor potencial de radón de la provincia de Tarragona.\n\nACM-2020 realiza mediciones profesionales de radón en Alforja, con experiencia en municipios de las sierras del Baix Camp donde la geología genera condiciones especialmente favorables para la concentración de radón.',

  // === BARCELONA - ALT PENEDES ===
  'vilafranca-del-penedes': 'Vilafranca del Penedès, capital de la comarca del Alt Penedès, está clasificada en Zona I (exposición media) al gas radón. La geología de la depresión del Penedès, con depósitos sedimentarios cuaternarios sobre sustratos calizos y margosos, genera niveles moderados de radón. La actividad vitivinícola histórica de la comarca ha dejado un patrimonio de cellers y edificaciones con plantas subterráneas donde la acumulación de radón puede ser significativa.\n\nACM-2020 ofrece servicios de medición de radón en Vilafranca del Penedès, con especial atención a bodegas, cellers y centros de trabajo con plantas bajo rasante, donde la medición es obligatoria según el RD 1029/2022.',

  'sant-sadurni-danoia': 'Sant Sadurní d\'Anoia, en el Alt Penedès, se encuentra clasificado en Zona I (exposición media) al gas radón. Capital del cava, el municipio se asienta sobre formaciones sedimentarias de la depresión prelitoral que generan niveles moderados de radón. Las numerosas cavas y bodegas subterráneas del municipio representan espacios donde la concentración de radón puede alcanzar niveles significativos.\n\nACM-2020 realiza mediciones de radón en Sant Sadurní d\'Anoia, con experiencia en espacios subterráneos vinculados a la industria del cava y el vino, donde la ventilación natural es limitada y los niveles de radón requieren verificación.',

  'gelida': 'Gelida, en la comarca del Alt Penedès, está clasificada en Zona I (exposición media) al gas radón. Su ubicación en la transición entre la depresión del Penedès y las estribaciones de la Serralada Prelitoral, sobre materiales sedimentarios y calizos, genera niveles moderados de radón que aconsejan la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Gelida, proporcionando informes técnicos conformes al RD 1029/2022 para viviendas y centros de trabajo del municipio.',

  // === BARCELONA - ANOIA (additional) ===
  'vilanova-del-cami': 'Vilanova del Cami, en la comarca de la Anoia, está clasificada en Zona II (exposición alta) al gas radón. Su proximidad a Igualada y su ubicación en la depresión central catalana, sobre sustratos sedimentarios y graníticos, genera condiciones favorables para niveles elevados de radón en el subsuelo.\n\nACM-2020 realiza mediciones profesionales de radón en Vilanova del Cami, con experiencia en la comarca de la Anoia donde la obligatoriedad de medición en centros de trabajo afecta a numerosas empresas del tejido industrial local.',

  'santa-margarida-de-montbui': 'Santa Margarida de Montbui, en la Anoia, se encuentra en Zona II (exposición alta) al gas radón. Situada en las estribaciones de la serra de Montbui, la geología del municipio combina materiales sedimentarios con sustratos más antiguos que favorecen la emanación de radón desde el subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Santa Margarida de Montbui, con atención a viviendas unifamiliares y centros de trabajo donde la medición es obligatoria según la normativa vigente.',

  'piera': 'Piera, en la comarca de la Anoia, está clasificada en Zona II (exposición alta) al gas radón. El municipio se extiende sobre formaciones geológicas diversas, desde depósitos aluviales del río Anoia hasta materiales graníticos del macizo de Montserrat, que generan niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Piera, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación para viviendas y centros de trabajo en esta zona de actuación prioritaria.',

  'capellades': 'Capellades, en la Anoia, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en el valle del río Anoia, sobre formaciones calizas y travertinos que evidencian actividad hidrogeológica, el municipio presenta condiciones favorables para la emanación de radón. La tradición papelera histórica de Capellades ha dejado edificaciones industriales que requieren evaluación.\n\nACM-2020 ofrece servicios de medición de radón en Capellades y la Anoia, con detectores pasivos de larga duración que proporcionan lecturas fiables de la concentración media anual conforme al RD 1029/2022.',

  'la-pobla-de-claramunt': 'La Pobla de Claramunt, en la Anoia, está clasificada en Zona II (exposición alta) al gas radón. Situada en el valle del río Anoia, la geología del municipio, con materiales sedimentarios sobre sustratos graníticos, genera niveles elevados de radón en el subsuelo.\n\nACM-2020 realiza mediciones profesionales de radón en La Pobla de Claramunt, ofreciendo un servicio integral de medición y asesoramiento conforme a la normativa vigente.',

  'els-hostalets-de-pierola': 'Els Hostalets de Pierola, en la Anoia, se encuentra en Zona II (exposición alta) al gas radón. Su ubicación entre la depresión del Penedès y la conca de la Anoia, sobre formaciones geológicas mixtas, genera niveles elevados de radón que hacen obligatoria la medición en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Els Hostalets de Pierola, con experiencia en municipios de la Anoia y conocimiento de las particularidades geológicas de la zona.',

  'masquefa': 'Masquefa, en la Anoia, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición geológica entre el Penedès y la Anoia, sobre sustratos que favorecen la emanación de radón. Su crecimiento residencial reciente hace especialmente relevante la verificación de niveles en viviendas de nueva construcción.\n\nACM-2020 realiza mediciones de radón en Masquefa, tanto en viviendas como en centros de trabajo, cumpliendo con los protocolos establecidos por el CSN.',

  'jorba': 'Jorba, en la comarca de la Anoia, está clasificada en Zona II (exposición alta) al gas radón. Este municipio de la Anoia interior se asienta sobre formaciones sedimentarias y evaporíticas de la depresión central que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Jorba, proporcionando informes técnicos conformes al RD 1029/2022 y asesoramiento sobre medidas de mitigación.',

  'odena': 'Odena, en la Anoia, se encuentra en Zona II (exposición alta) al gas radón. Situado al norte de Igualada, el municipio se extiende sobre formaciones geológicas de la depresión central catalana que favorecen la emanación de radón. El polígono industrial de Odena, uno de los más importantes de la Anoia, requiere verificación sistemática de niveles de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Odena, con atención especial a naves industriales y centros de trabajo donde la medición es obligatoria en plantas bajas y bajo rasante.',

  'santa-maria-de-miralles': 'Santa Maria de Miralles, en la Anoia, está clasificada en Zona II (exposición alta) al gas radón. Este municipio rural de la Anoia sur se asienta sobre formaciones calizas y margosas que, en combinación con los sustratos más profundos, generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Santa Maria de Miralles, adaptados a edificaciones rurales y masias donde el contacto directo con el terreno favorece la infiltración de radón.',

  // === BARCELONA - BAGES (additional) ===
  'sant-joan-de-vilatorrada': 'Sant Joan de Vilatorrada, en la comarca del Bages, está clasificado en Zona II (exposición alta) al gas radón. Adyacente a Manresa, el municipio comparte la geología del Bages central, con formaciones evaporíticas y sustratos graníticos que generan niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Joan de Vilatorrada, con experiencia en la comarca del Bages donde los niveles de radón pueden superar significativamente el umbral de referencia de 300 Bq/m3.',

  'santpedor': 'Santpedor, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. La geología del municipio, con predominio de materiales evaporíticos y margosos sobre base granítica, genera condiciones propicias para la emanación de radón desde el subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Santpedor, proporcionando informes técnicos y asesoramiento para viviendas y centros de trabajo en esta zona de actuación prioritaria.',

  'navarcles': 'Navarcles, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle del Llobregat, sobre formaciones evaporíticas y sedimentarias características del Bages, el municipio presenta condiciones geológicas que favorecen niveles elevados de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Navarcles, con detectores pasivos homologados y elaboración de informes según la normativa vigente.',

  'sallent': 'Sallent, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. La geología del municipio, marcada por depósitos potásicos y evaporíticos sobre sustratos más antiguos, genera condiciones favorables para la emanación de radón. La actividad minera histórica de Sallent ha dejado un subsuelo con características particulares que pueden afectar a la concentración del gas.\n\nACM-2020 ofrece servicios de medición de radón en Sallent, con atención a las particularidades geológicas derivadas de la historia minera del municipio.',

  'suria': 'Súria, en el Bages, está clasificada en Zona II (exposición alta) al gas radón. Al igual que otros municipios del Bages con tradición minera de potasa, Súria se asienta sobre formaciones evaporíticas y graníticas que generan niveles elevados de radón. Las cavidades subterráneas derivadas de la actividad minera pueden influir en la distribución del gas.\n\nACM-2020 realiza mediciones de radón en Súria, proporcionando un servicio profesional adaptado a las condiciones específicas del municipio y cumpliendo con las obligaciones del RD 1029/2022.',

  'cardona': 'Cardona, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. El municipio es conocido por su montaña de sal, un diapiro salino único que evidencia la intensa actividad geológica del subsuelo. Las formaciones evaporíticas y los materiales graníticos subyacentes generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Cardona, con conocimiento de la singular geología del municipio y experiencia en mediciones en la comarca del Bages.',

  'monistrol-de-montserrat': 'Monistrol de Montserrat, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Situado al pie de la montaña de Montserrat, sobre formaciones de conglomerados y materiales graníticos, el municipio presenta niveles elevados de radón. La geología singular de Montserrat, con sus fracturas y cavidades, favorece la migración del gas.\n\nACM-2020 realiza mediciones de radón en Monistrol de Montserrat, con experiencia en municipios del entorno de Montserrat donde la geología genera condiciones específicas para la concentración de radón.',

  'castellbell-i-el-vilar': 'Castellbell i el Vilar, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en el valle del Llobregat entre Montserrat y Sant Llorenç del Munt, la geología del municipio combina conglomerados con materiales graníticos que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Castellbell i el Vilar, proporcionando informes técnicos conformes a la normativa vigente para viviendas y centros de trabajo.',

  'sant-vicenç-de-castellet': 'Sant Vicenç de Castellet, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Situado en la confluencia del Llobregat y el Cardener, la geología del municipio presenta materiales sedimentarios sobre base granítica que favorecen la emanación de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Sant Vicenç de Castellet, con experiencia en la comarca del Bages y atención a los centros de trabajo donde la medición es obligatoria.',

  'el-pont-de-vilomara-i-rocafort': 'El Pont de Vilomara i Rocafort, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. La geología del municipio, en la transición entre el Bages y el Vallès, combina formaciones sedimentarias con sustratos graníticos que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en El Pont de Vilomara i Rocafort, con detectores pasivos de larga duración y elaboración de informes técnicos según el RD 1029/2022.',

  'artes': 'Artes, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. El municipio se asienta sobre formaciones evaporíticas y sedimentarias del Bages central que generan condiciones propicias para la emanación de radón desde el subsuelo.\n\nACM-2020 realiza mediciones de radón en Artes, proporcionando un servicio profesional integral que incluye medición, diagnóstico e informe técnico conforme a la normativa vigente.',

  'avinyó': 'Avinyó, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. La geología del municipio, con materiales sedimentarios y evaporíticos sobre sustratos graníticos del Bages norte, genera niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Avinyó, con experiencia en municipios rurales del Bages donde las viviendas unifamiliares y masias requieren atención específica por su contacto directo con el terreno.',

  'balsareny': 'Balsareny, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle del Llobregat, la geología del municipio presenta formaciones evaporíticas y sedimentarias que generan niveles elevados de radón en el subsuelo.\n\nACM-2020 realiza mediciones de radón en Balsareny, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación cuando los niveles superan el umbral de referencia.',

  'callus': 'Callus, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. Próximo a Manresa, el municipio comparte la geología del Bages central con sus formaciones evaporíticas y sustratos que favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Callus, cumpliendo con los protocolos del CSN y proporcionando informes detallados para centros de trabajo y viviendas.',

  'sant-fruitós-de-bages': 'Sant Fruitós de Bages, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Adyacente a Manresa, el municipio cuenta con un importante polígono industrial donde la medición de radón es obligatoria en centros de trabajo situados en planta baja o bajo rasante según el RD 1029/2022.\n\nACM-2020 realiza mediciones profesionales de radón en Sant Fruitós de Bages, con especial atención a naves industriales y centros logísticos del municipio.',

  'sant-salvador-de-guardiola': 'Sant Salvador de Guardiola, en el Bages, se encuentra en Zona II (exposición alta) al gas radón. Situado entre Manresa y Montserrat, la geología del municipio presenta formaciones sedimentarias y evaporíticas que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sant Salvador de Guardiola, con atención a viviendas unifamiliares y masias dispersas donde el contacto directo con el terreno favorece la infiltración de radón.',

  'sant-mateu-de-bages': 'Sant Mateu de Bages, en el Bages, está clasificado en Zona II (exposición alta) al gas radón. Este municipio del Bages interior se asienta sobre formaciones evaporíticas y sedimentarias que generan condiciones propicias para niveles elevados de radón, especialmente en edificaciones rurales con cimentaciones tradicionales.\n\nACM-2020 realiza mediciones de radón en Sant Mateu de Bages, ofreciendo soluciones adaptadas a edificaciones rurales y de montaña del interior del Bages.',

  // === BARCELONA - BERGUEDA (additional) ===
  'gironella': 'Gironella, en el Berguedà, está clasificada en Zona II (exposición alta) al gas radón. Situada en el valle del Llobregat, la geología granítica del Prepirineo catalán genera niveles elevados de radón. El núcleo urbano histórico, con edificaciones textiles del siglo XIX a orillas del río, presenta características constructivas que pueden favorecer la acumulación.\n\nACM-2020 ofrece servicios de medición de radón en Gironella, con experiencia en el Berguedà y conocimiento del patrimonio industrial textil de la comarca.',

  'puig-reig': 'Puig-reig, en el Berguedà, se encuentra en Zona II (exposición alta) al gas radón. El municipio se asienta sobre formaciones graníticas del Prepirineo que generan niveles elevados de radón. Las antiguas colonias textiles del Llobregat, con sus edificaciones industriales y residenciales históricas, requieren evaluación frente al radón.\n\nACM-2020 realiza mediciones de radón en Puig-reig, con atención a las edificaciones de las colonias industriales y las viviendas del núcleo urbano.',

  'baga': 'Bagà, en el Berguedà, está clasificado en Zona II (exposición alta) al gas radón. Situado en el alto Berguedà, a los pies del Cadí-Moixeró, la geología granítica y metamórfica pirenaica genera niveles muy elevados de radón. La altitud del municipio y el clima de montaña favorecen períodos prolongados con ventilación reducida en interiores.\n\nACM-2020 ofrece servicios de medición de radón en Bagà y el alto Berguedà, con experiencia en edificaciones de montaña y conocimiento de las condiciones geológicas del Prepirineo.\n\nBagà limita con [Guardiola de Berguedà](/municipios/guardiola-de-bergueda), Urus, Das, [Alp](/municipios/alp), [Castellar de n\'Hug](/municipios/castellar-de-n-hug), todos ellos zonas de actuación prioritaria, y por otro lado, Gisclareny (Zona 1).',

  'guardiola-de-bergueda': 'Guardiola de Berguedà, en el Berguedà, se encuentra en Zona II (exposición alta) al gas radón. Este municipio del alto Berguedà, puerta de entrada al Cadí-Moixeró, se asienta sobre formaciones graníticas y metamórficas pirenaicas que generan niveles muy elevados de radón.\n\nACM-2020 realiza mediciones de radón en Guardiola de Berguedà, proporcionando informes técnicos para viviendas y centros de trabajo en esta zona de actuación prioritaria del Prepirineo.\n\nGuardiola de Berguedà limita con Bellver de Cerdanya, Riu de Cerdanya, Urus, [Bagà](/municipios/baga), [Castellar de n\'Hug](/municipios/castellar-de-n-hug), todos ellos zonas de actuación prioritaria, y por otro lado, Gisclareny, [La Pobla de Lillet](/municipios/la-pobla-de-lillet) y Sant Julia de Cerdanyola (municipios en Zona 1) y La Nou de Berguedà, Cercs y Vallcebre, municipios sin clasificar.',

  'cal-rosal': 'Cal Rosal, en el Berguedà, está clasificado en Zona II (exposición alta) al gas radón. Esta antigua colonia industrial del Llobregat se asienta sobre sustratos graníticos del Prepirineo que generan niveles elevados de radón. Las edificaciones de la colonia, con sus características constructivas del siglo XIX, son especialmente sensibles a la infiltración del gas.\n\nACM-2020 ofrece servicios de medición de radón en Cal Rosal, con experiencia en edificaciones históricas del patrimonio industrial del Berguedà.',

  'casserres': 'Casserres, en el Berguedà, se encuentra en Zona II (exposición alta) al gas radón. La geología granítica del municipio, en pleno Prepirineo catalán, genera condiciones propicias para la emanación de radón desde el subsuelo.\n\nACM-2020 realiza mediciones profesionales de radón en Casserres, proporcionando informes técnicos conformes al RD 1029/2022 para viviendas y centros de trabajo.',

  'la-pobla-de-lillet': 'La Pobla de Lillet, en el Berguedà, está clasificada en Zona II (exposición alta) al gas radón. Situada en el alto Berguedà pirenaico, a más de 800 metros de altitud, la geología granítica y metamórfica de la zona genera niveles muy elevados de radón. El clima frío de montaña implica largos períodos de calefacción con ventilación reducida.\n\nACM-2020 ofrece servicios de medición de radón en La Pobla de Lillet y el alto Berguedà, con experiencia en edificaciones de montaña donde las condiciones climáticas agravan la concentración de radón.',

  // === BARCELONA - OSONA (additional) ===
  'manlleu': 'Manlleu, en la comarca de Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en el meandro del Ter en la Plana de Vic, la geología del municipio presenta sustratos arcillosos y graníticos que favorecen la concentración de radón. El importante tejido industrial de Manlleu, heredero de la tradición textil, requiere verificación sistemática.\n\nACM-2020 realiza mediciones de radón en Manlleu, con atención a centros de trabajo industriales y viviendas del núcleo urbano donde la medición es obligatoria según el RD 1029/2022.',

  'tona': 'Tona, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Situado en el extremo sur de la Plana de Vic, sobre formaciones graníticas de la Serralada Prelitoral, Tona presenta niveles elevados de radón. Su proximidad al macizo del Montseny refuerza las condiciones geológicas favorables a la emanación.\n\nACM-2020 ofrece servicios de medición de radón en Tona, con experiencia en municipios de Osona donde la geología granítica genera niveles significativos de radón.',

  'centelles': 'Centelles, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en el paso natural entre el Vallès y la Plana de Vic, sobre formaciones graníticas de la Serralada Prelitoral, el municipio presenta niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Centelles, proporcionando informes técnicos y asesoramiento sobre medidas de mitigación para viviendas y centros de trabajo en esta zona de actuación prioritaria.',

  'taradell': 'Taradell, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en la Plana de Vic, sobre sustratos arcillosos y graníticos, el municipio presenta condiciones geológicas que favorecen niveles elevados de radón. El carácter residencial de Taradell, con numerosas viviendas unifamiliares, incrementa la superficie de contacto con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Taradell, con especial atención a viviendas unifamiliares y chalets donde la exposición potencial es mayor.',

  'roda-de-ter': 'Roda de Ter, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en un meandro del Ter, la geología del municipio presenta materiales graníticos y sedimentarios que favorecen la emanación de radón.\n\nACM-2020 realiza mediciones de radón en Roda de Ter, proporcionando un servicio profesional conforme al RD 1029/2022 para centros de trabajo y viviendas del municipio.',

  'seva': 'Seva, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en la transición entre la Plana de Vic y las Guilleries, sobre formaciones graníticas, Seva presenta niveles elevados de radón. Las viviendas aisladas y masias del municipio son especialmente vulnerables por su contacto directo con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Seva, con experiencia en edificaciones rurales de Osona y atención a las particularidades constructivas que favorecen la infiltración de radón.',

  'el-brull': 'El Brull, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Este municipio del Collsacabra, en las estribaciones del Montseny, se asienta sobre formaciones graníticas que generan niveles muy elevados de radón. La altitud y el carácter rural del municipio implican edificaciones en contacto directo con el sustrato rocoso.\n\nACM-2020 realiza mediciones de radón en El Brull, con experiencia en municipios rurales de montaña donde la geología granítica y las condiciones constructivas requieren atención específica.',

  'sant-hipolit-de-voltrega': 'Sant Hipòlit de Voltrega, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Situado en la Plana de Vic, la geología del municipio presenta sustratos que favorecen la emanación de radón. Su proximidad al río Ter y las formaciones montañosas circundantes contribuyen a los niveles registrados.\n\nACM-2020 ofrece servicios de medición de radón en Sant Hipòlit de Voltrega, proporcionando informes técnicos conformes a la normativa vigente.',

  'santa-eugenia-de-berga': 'Santa Eugenia de Berga, en Osona, está clasificada en Zona II (exposición alta) al gas radón. Situada en la Plana de Vic, próxima a las estribaciones del Montseny, la geología granítica de la zona genera niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Santa Eugenia de Berga, con experiencia en municipios de Osona y atención a viviendas y centros de trabajo donde la medición es obligatoria.',

  'sant-pere-de-torello': 'Sant Pere de Torelló, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Ubicado en la Plana de Vic norte, sobre materiales graníticos y metamórficos del Prepirineo, el municipio presenta condiciones geológicas que favorecen niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sant Pere de Torelló, proporcionando informes detallados y asesoramiento sobre medidas de mitigación.',

  'torello': 'Torelló, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en el valle del Ter, en el norte de la Plana de Vic, la geología del municipio presenta materiales graníticos y sedimentarios que generan niveles elevados de radón. El tejido industrial de Torelló, con naves y centros de trabajo, requiere verificación conforme al RD 1029/2022.\n\nACM-2020 realiza mediciones de radón en Torelló, con atención a centros de trabajo industriales y viviendas del municipio.',

  'les-masies-de-voltrega': 'Les Masies de Voltrega, en Osona, se encuentran en Zona II (exposición alta) al gas radón. Este municipio disperso de la Plana de Vic, con predominio de masias y viviendas unifamiliares, presenta una exposición potencial elevada debido al contacto directo de las edificaciones con el terreno granítico.\n\nACM-2020 ofrece servicios de medición de radón en Les Masies de Voltrega, especialmente orientados a masias y viviendas aisladas donde la superficie de contacto con el terreno es mayor.',

  'sant-quirze-de-besora': 'Sant Quirze de Besora, en Osona, está clasificado en Zona II (exposición alta) al gas radón. Situado en la confluencia del Ter y el Besòs, en la transición entre la Plana de Vic y el Ripollès, la geología granítica y metamórfica de la zona genera niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Quirze de Besora, proporcionando un servicio profesional adaptado a las condiciones geológicas del norte de Osona.',

  'prats-de-llucanes-osona': 'Sant Boi de Lluçanes, en Osona, se encuentra en Zona II (exposición alta) al gas radón. Este municipio del Lluçanes, en el interior de la Catalunya central, se asienta sobre formaciones geológicas que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sant Boi de Lluçanes, con experiencia en municipios rurales del interior de Catalunya.',

  // === BARCELONA - MOIANES / LLUÇANES ===
  'moià': 'Moià, capital del Moianès, está clasificada en Zona II (exposición alta) al gas radón. La geología del Moianès, con materiales sedimentarios y evaporíticos sobre sustratos graníticos del interior de Catalunya, genera condiciones propicias para niveles elevados de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Moià, con experiencia en la Catalunya central y atención a centros de trabajo y viviendas en esta zona de actuación prioritaria.',

  'calders': 'Calders, en el Moianès, se encuentra en Zona II (exposición alta) al gas radón. La geología del municipio, en la transición entre el Bages y el Vallès, presenta materiales sedimentarios sobre sustratos graníticos que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Calders, proporcionando informes técnicos conformes al RD 1029/2022.',

  'prats-de-llucanes': 'Prats de Lluçanes, capital del Lluçanes, está clasificado en Zona II (exposición alta) al gas radón. Situado en la altiplanicie del Lluçanes, en el interior de la Catalunya central, la geología del municipio genera condiciones favorables para niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Prats de Lluçanes, ofreciendo un servicio profesional adaptado a las necesidades de viviendas y centros de trabajo del Lluçanes.',

  // === BARCELONA - VALLES OCCIDENTAL (additional) ===
  'rubí': 'Rubí, en el Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. Su ubicación en la depresión del Vallès, sobre depósitos cuaternarios y sustratos graníticos de la Serralada Prelitoral, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Rubí, con atención a los polígonos industriales y centros de trabajo donde la verificación de niveles es recomendable según la normativa vigente.',

  'castellar-del-valles': 'Castellar del Vallès, en el Vallès Occidental, se encuentra clasificado en Zona I (exposición media) al gas radón. Su proximidad al Parc Natural de Sant Llorenç del Munt, con formaciones de conglomerados sobre base granítica, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Castellar del Vallès, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.',

  'vacarisses': 'Vacarisses, en el Vallès Occidental, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie de Montserrat, sobre formaciones de conglomerados y materiales graníticos, genera niveles elevados de radón. El carácter residencial del municipio, con predominio de viviendas unifamiliares, incrementa la superficie de contacto con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Vacarisses, con especial atención a viviendas unifamiliares y chalets situados sobre el sustrato rocoso del entorno de Montserrat.',

  'ullastrell': 'Ullastrell, en el Vallès Occidental, se encuentra en Zona I (exposición media) al gas radón. La geología del municipio, en la transición entre la depresión vallesana y las formaciones de Montserrat, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Ullastrell, proporcionando informes técnicos conformes a la normativa vigente para viviendas y centros de trabajo.',

  'badia-del-valles': 'Badia del Vallès, en el Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. Aunque se trata de un municipio de carácter urbano denso, la geología subyacente de la depresión vallesana, con depósitos sobre sustratos graníticos, genera niveles moderados de radón que aconsejan la medición preventiva en plantas bajas.\n\nACM-2020 ofrece servicios de medición de radón en Badia del Vallès, con atención a centros de trabajo y viviendas en planta baja o con sótano.',

  'cerdanyola-del-valles': 'Cerdanyola del Vallès, en el Vallès Occidental, se encuentra en Zona I (exposición media) al gas radón. Su ubicación al pie de la Serra de Collserola, sobre materiales graníticos paleozoicos, genera niveles moderados de radón. La presencia del campus de la Universitat Autònoma y el Parc Tecnològic hacen relevante la medición en estos centros de trabajo.\n\nACM-2020 realiza mediciones de radón en Cerdanyola del Vallès, con experiencia en edificios institucionales y centros de trabajo del Vallès Occidental.',

  'barbera-del-valles': 'Barberà del Vallès, en el Vallès Occidental, está clasificada en Zona I (exposición media) al gas radón. La geología de la depresión vallesana, con depósitos cuaternarios sobre sustratos graníticos, genera niveles moderados de radón. Los importantes polígonos industriales del municipio requieren verificación de niveles en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Barberà del Vallès, con atención especial a naves industriales y centros logísticos donde la medición es recomendable.',

  'sentmenat': 'Sentmenat, en el Vallès Occidental, se encuentra en Zona II (exposición alta) al gas radón. Su ubicación en la transición entre la depresión vallesana y las formaciones graníticas de la Serralada Prelitoral genera niveles elevados de radón.\n\nACM-2020 realiza mediciones de radón en Sentmenat, proporcionando informes técnicos para viviendas y centros de trabajo en esta zona de actuación prioritaria.',

  'palau-de-plegamans': 'Palau-solita i Plegamans, en el Vallès Occidental, está clasificado en Zona I (exposición media) al gas radón. La geología de la depresión vallesana genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Palau-solita i Plegamans, proporcionando informes conformes al RD 1029/2022.',

  'polinyà': 'Polinyà, en el Vallès Occidental, se encuentra en Zona I (exposición media) al gas radón. Los depósitos cuaternarios sobre sustratos graníticos de la depresión vallesana generan niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Polinyà, con atención a centros de trabajo y viviendas donde la verificación de niveles es recomendable.',

  'montcada-i-reixac': 'Montcada i Reixac, en el Vallès Occidental, está clasificado en Zona I (exposición media) al gas radón. Situado en la confluencia del Besòs y el Ripoll, al pie de la Serra de Collserola, la geología del municipio presenta materiales graníticos y metamórficos que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Montcada i Reixac, con especial atención a las zonas próximas a Collserola donde la geología granítica puede generar niveles superiores.',

  'ripollet': 'Ripollet, en el Vallès Occidental, se encuentra en zona baja de exposición al gas radón. No obstante, determinadas zonas del municipio próximas al río Ripoll pueden presentar niveles que aconsejen la medición preventiva, especialmente en edificios con sótano o plantas bajo rasante.\n\nACM-2020 ofrece servicios de medición de radón en Ripollet para propietarios y empresas que deseen verificar los niveles de radón en sus inmuebles.',

  'castellbisbal': 'Castellbisbal, en el Vallès Occidental, está clasificado en Zona I (exposición media) al gas radón. Su ubicación en la confluencia del Llobregat y el Anoia, con materiales sedimentarios sobre sustratos graníticos, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Castellbisbal, con atención a los polígonos industriales del municipio donde la medición en centros de trabajo es recomendable.',

  // === BARCELONA - VALLES ORIENTAL (additional) ===
  'granollers': 'Granollers, capital del Vallès Oriental, está clasificado en Zona I (exposición media) al gas radón. La geología de la depresión vallesana, con depósitos cuaternarios sobre sustratos graníticos y metamórficos, genera niveles moderados de radón. Como centro comercial e industrial del Vallès Oriental, el municipio cuenta con un amplio parque de edificios donde la medición preventiva es recomendable.\n\nACM-2020 ofrece servicios de medición de radón en Granollers, con atención a centros de trabajo, comercios y viviendas del municipio.',

  'mollet-del-valles': 'Mollet del Vallès, en el Vallès Oriental, se encuentra en zona baja de exposición al gas radón. No obstante, las zonas del municipio próximas a las formaciones de Collserola y Gallecs pueden presentar niveles que aconsejen la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Mollet del Vallès para propietarios y empresas que deseen verificar los niveles en sus inmuebles, proporcionando informes técnicos detallados.',

  'llinars-del-valles': 'Llinars del Vallès, en el Vallès Oriental, está clasificado en Zona I (exposición media) al gas radón. Su ubicación en la transición entre la depresión vallesana y la Serralada Litoral, sobre materiales graníticos, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Llinars del Vallès, proporcionando informes técnicos conformes al RD 1029/2022.\n\nLlinars del Vallès limita con [La Roca del Vallès](/municipios/la-roca-del-valles), [Santa Maria de Palautordera](/municipios/santa-maria-de-palautordera), [Vilalba Sasserra](/municipios/vilalba-sasserra), [Dosrius](/municipios/dosrius), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado [Cardedeu](/municipios/cardedeu) y Sant Antoni de Vilamajor (Zona 1).',

  'cardedeu': 'Cardedeu, en el Vallès Oriental, se encuentra en Zona I (exposición media) al gas radón. Situado al pie del Montseny, la proximidad a las formaciones graníticas de la Serralada Litoral genera niveles moderados de radón que aconsejan la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Cardedeu, con experiencia en municipios del entorno del Montseny.',

  'parets-del-valles': 'Parets del Vallès, en el Vallès Oriental, se encuentra en zona baja de exposición al gas radón. Sin embargo, la medición preventiva es recomendable en edificios con sótano y locales en planta baja, especialmente en las zonas próximas al río Tenes.\n\nACM-2020 ofrece servicios de medición de radón en Parets del Vallès para verificar los niveles en viviendas y centros de trabajo.',

  'les-franqueses-del-valles': 'Les Franqueses del Vallès, en el Vallès Oriental, están clasificadas en Zona I (exposición media) al gas radón. La geología del municipio, en la depresión vallesana próxima a las formaciones graníticas del Montseny, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Les Franqueses del Vallès, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.',

  'canovelles': 'Canovelles, en el Vallès Oriental, se encuentra en Zona I (exposición media) al gas radón. Adyacente a Granollers, el municipio comparte la geología de la depresión vallesana con niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Canovelles, con atención a centros de trabajo y viviendas donde la verificación de niveles es recomendable.',

  'aiguafreda': 'Aiguafreda, en el Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado en el congost del Congost, paso natural entre el Vallès y la Plana de Vic, la geología granítica de la zona genera niveles elevados de radón. La altitud y el entorno montañoso favorecen la concentración del gas.\n\nACM-2020 realiza mediciones de radón en Aiguafreda, con experiencia en municipios del congost donde la geología granítica genera condiciones favorables para la emanación de radón.',

  'bigues-i-riells': 'Bigues i Riells, en el Vallès Oriental, se encuentra en Zona II (exposición alta) al gas radón. Su ubicación en la vertiente sur de la Serralada Prelitoral, sobre formaciones graníticas, genera niveles elevados de radón. El carácter residencial disperso del municipio, con numerosas urbanizaciones y viviendas aisladas, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón en Bigues i Riells, con especial atención a urbanizaciones y viviendas unifamiliares donde el contacto directo con el terreno granítico favorece la infiltración de radón.\n\nBigues i Riells limita con [Caldes de Montbui](/municipios/caldes-de-montbui), [Figaró-Montmany](/municipios/figaro-montmany), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles), [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana), todos ellos zonas de actuación prioritaria, y por otro lado, Sant Feliu de Codines (Zona 1), y también limita con Sant Quirze Safaja, zona sin clasificar.',

  // === BARCELONA - BAIX LLOBREGAT (additional) ===
  'martorell': 'Martorell, en el Baix Llobregat, está clasificado en Zona I (exposición media) al gas radón. Situado en la confluencia del Llobregat y el Anoia, la geología del municipio presenta materiales sedimentarios sobre sustratos que generan niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Martorell, con atención a los importantes polígonos industriales y centros logísticos del municipio donde la medición es recomendable.',

  'abrera': 'Abrera, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. Su proximidad a Montserrat y la geología de transición entre la depresión del Llobregat y las formaciones montañosas generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Abrera, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.',

  'collbato': 'Collbató, en el Baix Llobregat, está clasificado en Zona II (exposición alta) al gas radón. Situado al pie de Montserrat, sobre formaciones de conglomerados y materiales graníticos, el municipio presenta niveles elevados de radón. Las Coves del Salnitre evidencian la permeabilidad del subsuelo y las condiciones favorables para la migración de gases.\n\nACM-2020 realiza mediciones de radón en Collbató, con conocimiento de la singular geología del entorno de Montserrat y experiencia en edificaciones situadas sobre sustratos rocosos permeables.',

  'el-hospitalet-de-llobregat': 'L\'Hospitalet de Llobregat, en el Barcelonès, se encuentra en zona baja de exposición al gas radón. No obstante, la densidad urbana del municipio y la presencia de numerosos sótanos y plantas bajo rasante hacen recomendable la medición preventiva en determinados edificios.\n\nACM-2020 ofrece servicios de medición de radón en L\'Hospitalet de Llobregat para empresas y propietarios que deseen verificar los niveles en sus inmuebles.',

  'cornella-de-llobregat': 'Cornellà de Llobregat, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Situado en el delta del Llobregat, sobre depósitos aluviales, el municipio presenta generalmente niveles bajos, aunque la medición preventiva es recomendable en edificios con sótano.\n\nACM-2020 realiza mediciones de radón en Cornellà de Llobregat, proporcionando informes técnicos para centros de trabajo y viviendas.',

  'sant-boi-de-llobregat': 'Sant Boi de Llobregat, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Las zonas del municipio próximas a las elevaciones de la Serralada Litoral pueden presentar niveles ligeramente superiores que aconsejen la medición.\n\nACM-2020 ofrece servicios de medición de radón en Sant Boi de Llobregat para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'gava': 'Gavà, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Sin embargo, las zonas interiores del municipio, próximas al macizo del Garraf, pueden presentar niveles puntuales que aconsejen la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Gavà, proporcionando informes técnicos detallados para viviendas y centros de trabajo.',

  'castelldefels': 'Castelldefels, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Las zonas del municipio próximas al macizo del Garraf, con formaciones calizas y dolomitas, pueden presentar niveles moderados que aconsejen la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Castelldefels, con atención a las zonas de contacto con el macizo del Garraf donde la geología puede generar niveles superiores.',

  'sant-feliu-de-llobregat': 'Sant Feliu de Llobregat, en el Baix Llobregat, se encuentra en zona baja de exposición al gas radón. Las zonas norte del municipio, próximas a Collserola, pueden presentar niveles moderados debido a la geología granítica del macizo.\n\nACM-2020 realiza mediciones de radón en Sant Feliu de Llobregat, con atención a las edificaciones situadas en las zonas de contacto con Collserola.',

  'sant-just-desvern': 'Sant Just Desvern, en el Baix Llobregat, está clasificado en Zona I (exposición media) al gas radón. Su ubicación al pie de la Serra de Collserola, sobre materiales graníticos paleozoicos, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 ofrece servicios de medición de radón en Sant Just Desvern, con especial atención a viviendas unifamiliares y edificios situados en las laderas de Collserola.',

  'el-papiol': 'El Papiol, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. Situado entre Collserola y el valle del Llobregat, la geología granítica del macizo genera niveles moderados de radón en el municipio.\n\nACM-2020 realiza mediciones de radón en El Papiol, proporcionando informes técnicos conformes al RD 1029/2022.',

  'begues': 'Begues, en el Baix Llobregat, está clasificada en Zona I (exposición media) al gas radón. Situado en el macizo del Garraf, sobre formaciones calizas y dolomitas, el municipio presenta niveles moderados de radón. El carácter residencial de Begues, con viviendas unifamiliares en contacto directo con el terreno, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón en Begues, con atención a viviendas unifamiliares y chalets del macizo del Garraf.',

  'cervelló': 'Cervelló, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. La geología del municipio, en la transición entre el valle del Llobregat y las formaciones montañosas del Ordal, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Cervelló, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.',

  'vallirana': 'Vallirana, en el Baix Llobregat, está clasificada en Zona I (exposición media) al gas radón. Su ubicación en el valle de la riera de Cervelló, entre formaciones calizas y materiales graníticos del Ordal, genera niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Vallirana, con atención a viviendas y centros de trabajo del municipio.',

  'corbera-de-llobregat': 'Corbera de Llobregat, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. Situada entre el valle del Llobregat y las formaciones del macizo del Ordal, la geología del municipio genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Corbera de Llobregat, proporcionando informes técnicos conformes a la normativa vigente.',

  'la-palma-de-cervello': 'La Palma de Cervelló, en el Baix Llobregat, está clasificada en Zona I (exposición media) al gas radón. La geología del municipio, en la transición entre el valle del Llobregat y las formaciones del Ordal, genera niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en La Palma de Cervelló, con informes técnicos conformes al RD 1029/2022.',

  'torrelles-de-llobregat': 'Torrelles de Llobregat, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. El municipio se sitúa sobre formaciones calizas del macizo del Garraf que generan niveles moderados de radón, especialmente en viviendas unifamiliares en contacto directo con el terreno.\n\nACM-2020 realiza mediciones de radón en Torrelles de Llobregat, con atención a viviendas unifamiliares y urbanizaciones del municipio.',

  'sant-andreu-de-la-barca': 'Sant Andreu de la Barca, en el Baix Llobregat, está clasificado en Zona I (exposición media) al gas radón. La geología del municipio, en el valle del Llobregat sobre depósitos sedimentarios, genera niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sant Andreu de la Barca, con atención a centros de trabajo y viviendas del municipio.',

  'sant-esteve-sesrovires': 'Sant Esteve Sesrovires, en el Baix Llobregat, se encuentra en Zona I (exposición media) al gas radón. Su ubicación próxima a Montserrat, con materiales sedimentarios sobre sustratos graníticos, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Esteve Sesrovires, proporcionando informes técnicos para viviendas y centros de trabajo del municipio.',

  // === BARCELONA - BARCELONES (additional) ===
  'santa-coloma-de-gramenet': 'Santa Coloma de Gramenet, en la comarca del Barcelonès, está clasificada en Zona II (exposición alta) al gas radón. Su ubicación al pie de la Serra de Marina, sobre formaciones graníticas y metamórficas de la Serralada Litoral, genera niveles elevados de radón, especialmente en las zonas altas del municipio próximas a la sierra. El Real Decreto 1029/2022 establece la obligatoriedad de medir la concentración de radón en centros de trabajo de esta zona de actuación prioritaria.\n\nACM-2020 ofrece servicios profesionales de medición de radón en Santa Coloma de Gramenet, con atención a las edificaciones situadas en las laderas de la Serra de Marina y en las plantas bajas y sótanos del núcleo urbano.',

  // === BARCELONA - MARESME (additional) ===
  'montgat': 'Montgat, en la comarca del Maresme, está clasificado en Zona I (exposición media) al gas radón. Su ubicación en la costa, al pie de las formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Montgat, con atención a viviendas y centros de trabajo situados en las zonas próximas a la sierra.\n\nMontgat limita con [Badalona](/municipios/badalona), [Tiana](/municipios/tiana), [Alella](/municipios/alella) y [el Masnou](/municipios/el-masnou), todos ellos zonas de actuación prioritaria.',

  'tiana': 'Tiana, en el Maresme, se encuentra en Zona I (exposición media) al gas radón. Situado en las estribaciones de la Serralada Litoral, sobre formaciones graníticas, el municipio presenta niveles moderados de radón. Las viviendas unifamiliares del municipio, con contacto directo con el terreno granítico, son especialmente sensibles.\n\nACM-2020 ofrece servicios de medición de radón en Tiana, con especial atención a viviendas unifamiliares y urbanizaciones situadas sobre sustratos graníticos.\n\nTiana limita con [Montgat](/municipios/montgat), [Badalona](/municipios/badalona), [Alella](/municipios/alella), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles) y [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), todos ellos zonas de actuación prioritaria.',

  // === BARCELONA - GARRAF ===
  'vilanova-i-la-geltru': 'Vilanova i la Geltrú, capital del Garraf, se encuentra en zona baja de exposición al gas radón. No obstante, las zonas interiores del municipio, próximas al macizo del Garraf, pueden presentar niveles que aconsejen la medición preventiva en edificios con sótano.\n\nACM-2020 realiza mediciones de radón en Vilanova i la Geltrú, proporcionando informes técnicos para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'sitges': 'Sitges, en la comarca del Garraf, se encuentra en zona baja de exposición al gas radón. Las zonas del municipio próximas al macizo del Garraf y las formaciones calizas interiores pueden presentar niveles moderados. La medición preventiva es recomendable en edificios históricos del casco antiguo y en viviendas con sótano.\n\nACM-2020 ofrece servicios de medición de radón en Sitges, con atención a edificaciones del núcleo histórico y viviendas en contacto con el sustrato rocoso del Garraf.',

  'sant-pere-de-ribes': 'Sant Pere de Ribes, en el Garraf, se encuentra en zona baja de exposición al gas radón. Las zonas interiores próximas al macizo del Garraf pueden presentar niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Pere de Ribes para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'olivella': 'Olivella, en el Garraf, está clasificada en Zona I (exposición media) al gas radón. Su ubicación en el interior del macizo del Garraf, sobre formaciones calizas y dolomitas, genera niveles moderados de radón. El carácter disperso del municipio, con masias y urbanizaciones aisladas, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón en Olivella, con atención a viviendas unifamiliares y urbanizaciones del macizo del Garraf.',

  // === GIRONA - GIRONES (additional) ===
  'salt': 'Salt, en el Gironès, está clasificado en Zona I (exposición media) al gas radón. Adyacente a Girona, el municipio comparte la geología de la depresión del Ter-Onyar con niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Salt, proporcionando informes técnicos conformes al RD 1029/2022 para centros de trabajo y viviendas del municipio.',

  'sarria-de-ter': 'Sarrià de Ter, en el Gironès, se encuentra en Zona I (exposición media) al gas radón. Situado en el valle del Ter, al norte de Girona, la geología del municipio presenta materiales sedimentarios sobre sustratos que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Sarrià de Ter, con informes técnicos conformes a la normativa vigente.',

  // === GIRONA - SELVA (additional) ===
  'breda': 'Breda, en la comarca de la Selva, está clasificada en Zona II (exposición alta) al gas radón. Situada al pie del Montseny, sobre formaciones graníticas paleozoicas, Breda presenta niveles elevados de radón. El monasterio románico y el núcleo histórico del municipio, con edificaciones de piedra sobre sustrato granítico, son especialmente sensibles.\n\nACM-2020 realiza mediciones de radón en Breda, con experiencia en municipios del entorno del Montseny donde la geología granítica genera niveles significativos de radón.',

  'hostalric': 'Hostalric, en la Selva, se encuentra en Zona II (exposición alta) al gas radón. Situado sobre un promontorio basáltico, la geología del municipio combina materiales volcánicos con sustratos graníticos que generan niveles elevados de radón. El castillo y las murallas medievales de Hostalric se asientan directamente sobre este sustrato rocoso.\n\nACM-2020 ofrece servicios de medición de radón en Hostalric, con atención a las particularidades geológicas del municipio y las edificaciones del casco histórico.',

  'vidreres': 'Vidreres, en la Selva, está clasificada en Zona I (exposición media) al gas radón. La geología granítica de la depresión prelitoral genera niveles moderados de radón que hacen recomendable la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Vidreres, proporcionando informes técnicos conformes al RD 1029/2022 para viviendas y centros de trabajo.',

  'lloret-de-mar': 'Lloret de Mar, en la Selva, se encuentra en Zona I (exposición media) al gas radón. La costa de Lloret, con sus formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón. El importante parque hotelero y de servicios del municipio requiere verificación de niveles en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Lloret de Mar, con atención a establecimientos turísticos y centros de trabajo donde la medición es recomendable.',

  'blanes': 'Blanes, en la Selva, está clasificado en Zona I (exposición media) al gas radón. Situado en la transición entre la Costa Brava y la costa del Maresme, sobre formaciones graníticas de la Serralada Litoral, el municipio presenta niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Blanes, proporcionando informes técnicos para centros de trabajo y viviendas del municipio.',

  // === GIRONA - GARROTXA (additional) ===
  'les-preses': 'Les Preses, en la Garrotxa, está clasificada en Zona II (exposición alta) al gas radón. Situada en plena zona volcánica de la Garrotxa, sobre materiales volcánicos porosos y permeables, Les Preses presenta niveles elevados de radón. Los suelos volcánicos permiten la circulación y emanación del gas con facilidad.\n\nACM-2020 ofrece servicios de medición de radón en Les Preses, con experiencia en la zona volcánica de la Garrotxa donde la geología genera condiciones excepcionales para la concentración de radón.',

  'santa-pau': 'Santa Pau, en la Garrotxa, se encuentra en Zona II (exposición alta) al gas radón. Este municipio medieval se sitúa en el corazón de la zona volcánica, rodeado de conos volcánicos y coladas de lava que generan suelos porosos y permeables al radón. El casco histórico de piedra es especialmente vulnerable.\n\nACM-2020 realiza mediciones de radón en Santa Pau, con conocimiento de la singular geología volcánica de la Garrotxa y atención a las edificaciones históricas del municipio.',

  'la-vall-den-bas': 'La Vall d\'en Bas, en la Garrotxa, está clasificada en Zona II (exposición alta) al gas radón. Situada en un amplio valle volcánico, la geología del municipio presenta materiales volcánicos y sedimentarios que generan niveles elevados de radón.\n\nACM-2020 ofrece servicios de medición de radón en La Vall d\'en Bas, con experiencia en la zona volcánica de la Garrotxa y atención a las edificaciones rurales y masias del valle.',

  'sant-joan-les-fonts': 'Sant Joan les Fonts, en la Garrotxa, se encuentra en Zona II (exposición alta) al gas radón. La geología volcánica del municipio, con coladas de lava y materiales basálticos, genera condiciones favorables para la emanación de radón. Las características coladas de lava superpuestas del Boscarró son un ejemplo de la permeabilidad del subsuelo local.\n\nACM-2020 realiza mediciones de radón en Sant Joan les Fonts, con experiencia en la zona volcánica de la Garrotxa.',

  'castellfollit-de-la-roca': 'Castellfollit de la Roca, en la Garrotxa, está clasificado en Zona II (exposición alta) al gas radón. El municipio, famoso por su espectacular risco basáltico sobre el río Fluvià, se asienta sobre coladas de lava que evidencian la intensa actividad volcánica de la zona. Los materiales basálticos porosos favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Castellfollit de la Roca, con conocimiento de la geología volcánica del municipio y experiencia en edificaciones construidas sobre sustrato basáltico.',

  // === GIRONA - RIPOLLES (additional) ===
  'ribes-de-freser': 'Ribes de Freser, en el Ripollès, está clasificada en Zona II (exposición alta) al gas radón. Situado en el valle del Freser, en pleno Pirineo catalán, la geología granítica y metamórfica de la zona genera niveles muy elevados de radón. La altitud del municipio, superior a 900 metros, implica largos períodos con ventilación reducida.\n\nACM-2020 realiza mediciones de radón en Ribes de Freser, con experiencia en municipios del Pirineo donde la combinación de geología granítica y clima de montaña genera concentraciones significativas.',

  'sant-joan-de-les-abadesses-2': 'Gombren, en el Ripollès, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico se asienta sobre formaciones graníticas y metamórficas que generan niveles elevados de radón. El carácter rural y disperso del municipio, con masias y edificaciones de piedra, favorece el contacto directo con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Gombren, con experiencia en municipios rurales del Ripollès donde las edificaciones tradicionales requieren atención específica.',

  // === GIRONA - CERDANYA (additional) ===
  'llívia': 'Llívia, en la Cerdanya, está clasificada en Zona II (exposición alta) al gas radón. Este enclave español en territorio francés, a más de 1.200 metros de altitud, se asienta sobre formaciones graníticas pirenaicas que generan niveles muy elevados de radón. El clima continental de alta montaña implica largos períodos de calefacción con ventilación reducida.\n\nACM-2020 realiza mediciones de radón en Llívia, con experiencia en la Cerdanya donde la geología granítica pirenaica y las condiciones climáticas hacen especialmente importante la verificación de los niveles de radón.',

  // === GIRONA - EMPORDA (additional) ===
  'la-bisbal-demporda': 'La Bisbal d\'Empordà, capital del Baix Empordà, está clasificada en Zona I (exposición media) al gas radón. La geología del municipio, con materiales sedimentarios sobre sustratos graníticos del macizo de les Gavarres, genera niveles moderados de radón. La tradición cerámica de La Bisbal ha generado edificaciones industriales con plantas bajas en contacto con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en La Bisbal d\'Empordà, con atención a talleres cerámicos y centros de trabajo del municipio.',

  'roses': 'Roses, en el Alt Empordà, se encuentra clasificada en Zona I (exposición media) al gas radón. La geología del municipio combina formaciones metamórficas del Cap de Creus con depósitos aluviales de la bahía, generando niveles moderados de radón que aconsejan la medición preventiva, especialmente en las zonas próximas a las elevaciones rocosas.\n\nACM-2020 realiza mediciones de radón en Roses, con atención a establecimientos turísticos y centros de trabajo donde la medición es recomendable según el RD 1029/2022.',

  'palafrugell': 'Palafrugell, en el Baix Empordà, está clasificado en Zona I (exposición media) al gas radón. La geología del municipio, entre la costa y el macizo de les Gavarres, presenta formaciones graníticas que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Palafrugell, con atención a viviendas y centros de trabajo del municipio y los núcleos costeros de Calella, Llafranc y Tamariu.',

  'sant-feliu-de-guixols': 'Sant Feliu de Guíxols, en el Baix Empordà, se encuentra clasificado en Zona I (exposición media) al gas radón. La geología costera del municipio, con formaciones graníticas de la Serralada Litoral, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Sant Feliu de Guíxols, con atención a centros de trabajo y viviendas del municipio.',

  'palamos': 'Palamós, en el Baix Empordà, está clasificado en Zona I (exposición media) al gas radón. La geología del municipio combina formaciones graníticas costeras con depósitos sedimentarios que generan niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Palamós, proporcionando informes técnicos conformes al RD 1029/2022 para centros de trabajo y viviendas.',

  'calonge': 'Calonge, en el Baix Empordà, se encuentra en Zona I (exposición media) al gas radón. La geología del municipio, entre la costa y las formaciones graníticas del interior, genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Calonge, con atención a viviendas y centros de trabajo del municipio y el núcleo costero de Sant Antoni.',

  // === LLEIDA (additional) ===
  'lleida': 'Lleida, capital de provincia, se encuentra en zona baja de exposición al gas radón. Situada en la depresión central catalana, sobre depósitos aluviales del Segre, el municipio presenta generalmente niveles bajos de radón. No obstante, la medición preventiva es recomendable en edificios con sótano y plantas bajo rasante.\n\nACM-2020 ofrece servicios de medición de radón en Lleida, proporcionando informes técnicos para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'balaguer': 'Balaguer, en la comarca de la Noguera, está clasificada en Zona I (exposición media) al gas radón. Situado en el valle del Segre, en la transición entre la depresión central y el Prepirineo, la geología del municipio genera niveles moderados de radón.\n\nACM-2020 realiza mediciones de radón en Balaguer, proporcionando informes técnicos conformes al RD 1029/2022 para centros de trabajo y viviendas.',

  'tarrega': 'Tàrrega, capital de la comarca del Urgell, se encuentra en zona baja de exposición al gas radón. Situada en la depresión central catalana, sobre depósitos sedimentarios, el municipio presenta generalmente niveles bajos.\n\nACM-2020 ofrece servicios de medición de radón en Tàrrega para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'mollerussa': 'Mollerussa, capital del Pla d\'Urgell, se encuentra en zona baja de exposición al gas radón. La llanura del Pla d\'Urgell, sobre depósitos aluviales, presenta generalmente niveles bajos de radón.\n\nACM-2020 realiza mediciones de radón en Mollerussa para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'cervera': 'Cervera, capital de la Segarra, está clasificada en Zona I (exposición media) al gas radón. Situada en la meseta de la Segarra, sobre formaciones calizas y margosas de la depresión central, el municipio presenta niveles moderados de radón.\n\nACM-2020 ofrece servicios de medición de radón en Cervera, proporcionando informes técnicos conformes a la normativa vigente.',

  // === TARRAGONA (additional) ===
  'tarragona': 'Tarragona, capital de provincia, se encuentra en zona baja de exposición al gas radón. La llanura costera del Camp de Tarragona, sobre depósitos sedimentarios, presenta generalmente niveles bajos. Sin embargo, las zonas próximas a las elevaciones del interior pueden registrar niveles moderados.\n\nACM-2020 realiza mediciones de radón en Tarragona, proporcionando informes técnicos para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'reus': 'Reus, en la comarca del Baix Camp, se encuentra en zona baja de exposición al gas radón. La llanura del Camp de Tarragona presenta generalmente niveles bajos, aunque las zonas del municipio próximas a las sierras interiores pueden registrar niveles moderados.\n\nACM-2020 ofrece servicios de medición de radón en Reus para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'el-vendrell': 'El Vendrell, capital del Baix Penedès, se encuentra en zona baja de exposición al gas radón. La llanura costera del Baix Penedès presenta generalmente niveles bajos de radón.\n\nACM-2020 realiza mediciones de radón en El Vendrell, proporcionando informes técnicos para viviendas y centros de trabajo.',

  'amposta': 'Amposta, en la comarca del Montsia, se encuentra en zona baja de exposición al gas radón. Situada en el delta del Ebro, sobre depósitos aluviales, el municipio presenta generalmente niveles bajos de radón.\n\nACM-2020 ofrece servicios de medición de radón en Amposta para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  'cambrils': 'Cambrils, en la comarca del Baix Camp, se encuentra en zona baja de exposición al gas radón. La franja costera del Baix Camp presenta generalmente niveles bajos, aunque las zonas interiores próximas a las sierras pueden registrar niveles moderados.\n\nACM-2020 realiza mediciones de radón en Cambrils, proporcionando informes técnicos para centros de trabajo y viviendas.',

  'calafell': 'Calafell, en la comarca del Baix Penedès, se encuentra en zona baja de exposición al gas radón. La franja costera del Baix Penedès presenta generalmente niveles bajos de radón.\n\nACM-2020 ofrece servicios de medición de radón en Calafell para propietarios y empresas que deseen verificar los niveles en sus inmuebles.',

  // === MARESME (new municipalities) ===
  'alella': 'Alella, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Situada en las laderas de la Serralada Litoral, entre el litoral y las formaciones graníticas del macizo de la Marina, el municipio presenta sustratos paleozoicos que favorecen la emanación de radón. La tradición vinícola de Alella, con la denominación de origen más antigua de Catalunya, refleja unos suelos graníticos con alta permeabilidad al gas.\n\nACM-2020 ofrece servicios profesionales de medición de radón en Alella, con especial atención a las viviendas unifamiliares y masias del municipio donde el contacto directo con el terreno granítico incrementa el riesgo de infiltración. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nAlella limita con [Vallromanes](/municipios/vallromanes), [Teià](/municipios/teia), [el Masnou](/municipios/el-masnou), [Montgat](/municipios/montgat), [Tiana](/municipios/tiana) y [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), todos ellos zonas de actuación prioritaria.',

  'cabrera-de-mar': 'Cabrera de Mar, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, entre el litoral mediterráneo y las cimas del macizo de la Marina. Los restos arqueológicos iberos y romanos del Turo d\'en Bosca evidencian la antigüedad de los sustratos rocosos que favorecen la emanación de radón.\n\nACM-2020 realiza mediciones profesionales de radón en Cabrera de Mar, tanto en viviendas como en centros de trabajo. Las edificaciones situadas en las laderas del macizo de la Marina requieren especial atención por su proximidad al sustrato granítico.\n\nCabrera de Mar limita con [Cabrils](/municipios/cabrils), [Argentona](/municipios/argentona), [Mataró](/municipios/mataro), zonas de actuación prioritaria, y [Vilassar de Mar](/municipios/vilassar-de-mar), Zona 1.',

  'tordera': 'Tordera, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Situada en la confluencia de la Tordera con la Serralada Litoral, el municipio se asienta sobre formaciones graníticas del macizo del Montnegre-Corredor. El amplio valle fluvial de la Tordera, con depósitos aluviales sobre base granítica, facilita la migración del gas hacia la superficie.\n\nACM-2020 ofrece servicios de medición de radón en Tordera, con atención tanto al núcleo urbano como a las urbanizaciones y masias dispersas del municipio. La medición en centros de trabajo es obligatoria conforme al RD 1029/2022.\n\nTordera limita con [Fogars de la Selva](/municipios/fogars-de-la-selva), Macanet de la Selva, [Lloret de Mar](/municipios/lloret-de-mar), [Sant Celoni](/municipios/sant-celoni), [Blanes](/municipios/blanes), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Pineda de Mar](/municipios/pineda-de-mar), [Santa Susanna](/municipios/santa-susanna) y [Palafolls](/municipios/palafolls), todos ellos zonas de actuación prioritaria.',

  'arenys-de-mar': 'Arenys de Mar, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se extiende desde la costa hasta las primeras estribaciones de la Serralada Litoral, sobre formaciones graníticas y metamórficas que favorecen la emanación de radón. Su puerto pesquero histórico y el núcleo urbano denso cuentan con edificaciones antiguas especialmente vulnerables.\n\nACM-2020 realiza mediciones de radón en Arenys de Mar, con atención a edificios del casco histórico y viviendas en contacto con el sustrato granítico. El servicio incluye detectores pasivos de larga duración conformes a la normativa vigente.\n\nArenys de Mar limita con [Arenys de Munt](/municipios/arenys-de-munt), [Canet de Mar](/municipios/canet-de-mar), [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt) y [Caldes d\'Estrac](/municipios/caldes-d-estrac), todos ellos zonas de actuación prioritaria.',

  'cabrils': 'Cabrils, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este municipio residencial se sitúa sobre las formaciones graníticas de la Serralada Litoral, en la vertiente meridional del macizo de la Marina. El predominio de viviendas unifamiliares y urbanizaciones incrementa la superficie de contacto con el terreno y, por tanto, el riesgo de infiltración de radón.\n\nACM-2020 ofrece servicios de medición de radón en Cabrils, especialmente orientados a viviendas unifamiliares y chalets. La verificación de niveles es obligatoria en centros de trabajo ubicados en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nCabrils limita con [Òrrius](/municipios/orrius), [Argentona](/municipios/argentona), [Cabrera de Mar](/municipios/cabrera-de-mar) y [Vilassar de Dalt](/municipios/vilassar-de-dalt), todos ellos zonas de actuación prioritaria, y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar) (Zona 1).',

  'sant-andreu-de-llavaneres': 'Sant Andreu de Llavaneres, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se extiende desde la línea de costa hasta las formaciones graníticas de la Serralada Litoral, con sustratos paleozoicos que favorecen la emanación de radón. El carácter residencial del municipio, con numerosas viviendas unifamiliares y campos de golf, incrementa la exposición potencial.\n\nACM-2020 realiza mediciones de radón en Sant Andreu de Llavaneres, con especial atención a urbanizaciones y viviendas aisladas donde el contacto con el terreno granítico es mayor. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Andreu de Llavaneres limita con [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt), [Mataró](/municipios/mataro) y [Dosrius](/municipios/dosrius), todos ellos zonas de actuación prioritaria.',

  'sant-cebria-de-vallalta': 'Sant Cebrià de Vallalta, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en el interior del Maresme, entre los macizos del Montnegre y el Corredor, el municipio se asienta sobre formaciones graníticas que generan niveles elevados de radón. El carácter rural y disperso de la edificación favorece el contacto directo con el terreno.\n\nACM-2020 ofrece servicios de medición de radón en Sant Cebrià de Vallalta, con atención a masias, viviendas aisladas y centros de trabajo del municipio donde la medición es obligatoria conforme al RD 1029/2022.\n\nSant Cebrià de Vallalta limita con [Sant Celoni](/municipios/sant-celoni), [Tordera](/municipios/tordera), [Pineda de Mar](/municipios/pineda-de-mar), [Calella](/municipios/calella), [Sant Pol de Mar](/municipios/sant-pol-de-mar), [Canet de Mar](/municipios/canet-de-mar) y [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), todos ellos zonas de actuación prioritaria.',

  'santa-susanna': 'Santa Susanna, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Este municipio costero se sitúa entre la franja litoral y las estribaciones del macizo del Montnegre, sobre formaciones graníticas que favorecen la emanación de radón. La actividad turística del municipio, con numerosos establecimientos hoteleros, requiere verificación de niveles de radón.\n\nACM-2020 realiza mediciones de radón en Santa Susanna, con atención a establecimientos turísticos y centros de trabajo donde la medición es obligatoria según el RD 1029/2022. El servicio incluye detectores pasivos de larga duración y elaboración de informes técnicos.\n\nSanta Susanna limita con [Tordera](/municipios/tordera), [Palafolls](/municipios/palafolls), [Malgrat de Mar](/municipios/malgrat-de-mar) y [Pineda de Mar](/municipios/pineda-de-mar), todos ellos zonas de actuación prioritaria.',

  'vilassar-de-dalt': 'Vilassar de Dalt, en la comarca del Maresme, se encuentra en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre las formaciones graníticas de la Serralada Litoral, en la vertiente sur del macizo de la Marina. Los sustratos paleozoicos y la presencia de viñas y campos sobre terrenos permeables evidencian la geología favorable a la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Vilassar de Dalt, con atención a viviendas unifamiliares y edificaciones en contacto directo con el sustrato granítico. La medición en centros de trabajo es obligatoria conforme al RD 1029/2022.\n\nVilassar de Dalt limita con [Vilanova del Vallès](/municipios/vilanova-del-valles), [Òrrius](/municipios/orrius), [Cabrils](/municipios/cabrils), [Premià de Dalt](/municipios/premia-de-dalt) y [Vallromanes](/municipios/vallromanes), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar) (Zona 1).',

  'arenys-de-munt': 'Arenys de Munt, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en el interior del Maresme, sobre formaciones graníticas de la Serralada Litoral, el municipio presenta sustratos paleozoicos con alta capacidad de emanación de radón. La orografía montañosa y los torrentes que bajan hacia la costa evidencian la fracturación del sustrato rocoso.\n\nACM-2020 realiza mediciones profesionales de radón en Arenys de Munt, con experiencia en municipios del interior del Maresme donde la geología granítica genera niveles elevados. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nArenys de Munt limita con [Vallgorguina](/municipios/vallgorguina), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Canet de Mar](/municipios/canet-de-mar), [Arenys de Mar](/municipios/arenys-de-mar), [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt) y [Dosrius](/municipios/dosrius), todos ellos zonas de actuación prioritaria.',

  'pineda-de-mar': 'Pineda de Mar, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. El municipio se extiende entre la costa y las estribaciones del macizo del Montnegre, sobre formaciones graníticas que favorecen la emanación de radón. Su importancia como destino turístico, con numerosos hoteles y apartamentos, hace relevante la verificación de niveles de radón en establecimientos de uso público.\n\nACM-2020 ofrece servicios de medición de radón en Pineda de Mar, tanto para viviendas como para establecimientos turísticos y centros de trabajo. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nPineda de Mar limita con [Tordera](/municipios/tordera), [Santa Susanna](/municipios/santa-susanna), [Calella](/municipios/calella) y [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), todos ellos zonas de actuación prioritaria.',

  'vilassar-de-mar': 'Vilassar de Mar, en la comarca del Maresme, está clasificado en Zona I (exposición media) al gas radón. Situado en la franja costera del Maresme, el municipio se asienta sobre depósitos aluviales y litorales que atenúan parcialmente la emanación de radón respecto a los municipios interiores. No obstante, la proximidad a las formaciones graníticas de la Serralada Litoral genera niveles moderados que aconsejan la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Vilassar de Mar, con atención a edificios con sótano y locales en planta baja en contacto con el terreno. El servicio incluye detectores pasivos de larga duración y elaboración de informes según la normativa vigente.\n\nVilassar de Mar limita con [Premià de Dalt](/municipios/premia-de-dalt), [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Cabrils](/municipios/cabrils), [Cabrera de Mar](/municipios/cabrera-de-mar), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado, [Premià de Mar](/municipios/premia-de-mar), considerado Zona 1.',

  'canet-de-mar': 'Canet de Mar, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. El municipio se extiende desde el litoral hasta las estribaciones de la Serralada Litoral, sobre formaciones graníticas y metamórficas. El patrimonio modernista del municipio, con obras de Lluís Domènech i Montaner, se asienta sobre sustratos que favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Canet de Mar, con atención tanto a edificios históricos como a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nCanet de Mar limita con [Arenys de Munt](/municipios/arenys-de-munt), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Sant Pol de Mar](/municipios/sant-pol-de-mar) y [Arenys de Mar](/municipios/arenys-de-mar), todos ellos zonas de actuación prioritaria.',

  'caldes-d-estrac': 'Caldes d\'Estrac, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este pequeño municipio costero, conocido históricamente por sus aguas termales, se asienta sobre formaciones graníticas que favorecen tanto la surgencia de aguas mineromedicinales como la emanación de radón. La presencia de aguas termales es un indicador de actividad geológica y fracturación del sustrato.\n\nACM-2020 realiza mediciones de radón en Caldes d\'Estrac, con atención a viviendas, establecimientos termales y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nCaldes d\'Estrac limita con [Arenys de Mar](/municipios/arenys-de-mar) y [Sant Vicenç de Montalt](/municipios/sant-vicenc-de-montalt), todos ellos zonas de actuación prioritaria.',

  'sant-iscle-de-vallalta': 'Sant Iscle de Vallalta, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en pleno macizo del Montnegre-Corredor, el municipio se asienta sobre formaciones graníticas paleozoicas que generan niveles elevados de radón. Su carácter rural y montañoso, con masias y edificaciones dispersas, incrementa la exposición potencial.\n\nACM-2020 ofrece servicios de medición de radón en Sant Iscle de Vallalta, con experiencia en municipios del interior del Maresme donde la geología granítica genera condiciones muy favorables para la emanación. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Iscle de Vallalta limita con [Sant Celoni](/municipios/sant-celoni), [Tordera](/municipios/tordera), [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Canet de Mar](/municipios/canet-de-mar), [Arenys de Munt](/municipios/arenys-de-munt) y [Vallgorguina](/municipios/vallgorguina), todos ellos zonas de actuación prioritaria.',

  'premia-de-mar': 'Premià de Mar, en la comarca del Maresme, está clasificado en Zona I (exposición media) al gas radón. Situado en la franja costera del Maresme, el municipio se asienta sobre depósitos litorales y aluviales que moderan la emanación de radón respecto a los municipios interiores. La proximidad a las formaciones graníticas de la Serralada Litoral genera niveles que hacen recomendable la medición preventiva.\n\nACM-2020 realiza mediciones de radón en Premià de Mar, con atención a edificios con sótano y locales comerciales en planta baja. El servicio incluye la instalación de detectores pasivos y la elaboración de informes conformes a la normativa vigente.\n\nPremià de Mar limita con [Premià de Dalt](/municipios/premia-de-dalt), [Teià](/municipios/teia) y [el Masnou](/municipios/el-masnou), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar), considerado Zona 1.',

  'teia': 'Teià, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en las laderas de la Serralada Litoral, sobre formaciones graníticas paleozoicas que favorecen la emanación de radón. El carácter residencial del municipio, con predominio de viviendas unifamiliares rodeadas de vegetación, incrementa la superficie de contacto con el terreno granítico.\n\nACM-2020 ofrece servicios de medición de radón en Teià, con especial atención a viviendas unifamiliares y chalets donde la infiltración de radón puede ser significativa. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nTeià limita con [el Masnou](/municipios/el-masnou), [Premià de Dalt](/municipios/premia-de-dalt), [Vallromanes](/municipios/vallromanes) y [Alella](/municipios/alella), todos ellos zonas de actuación prioritaria.',

  'orrius': 'Òrrius, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este pequeño municipio del interior del Maresme se sitúa sobre formaciones graníticas de la Serralada Litoral, en la vertiente sur del macizo de la Marina. Su carácter eminentemente rural, con masias y viviendas aisladas sobre terreno granítico, genera condiciones muy favorables para la infiltración de radón.\n\nACM-2020 realiza mediciones de radón en Òrrius, con atención a masias y viviendas unifamiliares donde el contacto directo con el sustrato granítico es determinante. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nÒrrius limita con [Argentona](/municipios/argentona), [La Roca del Vallès](/municipios/la-roca-del-valles), [Cabrils](/municipios/cabrils), [Vilassar de Dalt](/municipios/vilassar-de-dalt) y [Vilanova del Vallès](/municipios/vilanova-del-valles), todos ellos zonas de actuación prioritaria.',

  'palafolls': 'Palafolls, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en el tramo bajo del río Tordera, el municipio se asienta sobre depósitos aluviales con base granítica que favorecen la emanación de radón. La proximidad al macizo del Montnegre refuerza el potencial de concentración del gas en el subsuelo.\n\nACM-2020 ofrece servicios de medición de radón en Palafolls, con atención a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nPalafolls limita con [Santa Susanna](/municipios/santa-susanna), [Tordera](/municipios/tordera), [Blanes](/municipios/blanes) y [Malgrat de Mar](/municipios/malgrat-de-mar), todos ellos zonas de actuación prioritaria.',

  'calella': 'Calella, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. Este municipio costero, importante destino turístico, se extiende entre el litoral y las estribaciones del macizo del Montnegre sobre formaciones graníticas que favorecen la emanación de radón. Los numerosos establecimientos hoteleros y residenciales requieren verificación de niveles de radón.\n\nACM-2020 realiza mediciones de radón en Calella, con atención a hoteles, edificios residenciales y centros de trabajo donde la medición es obligatoria según el RD 1029/2022. El servicio incluye detectores pasivos de larga duración y elaboración de informes técnicos.\n\nCalella limita con [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Pineda de Mar](/municipios/pineda-de-mar) y [Sant Pol de Mar](/municipios/sant-pol-de-mar), todos ellos zonas de actuación prioritaria.',

  'malgrat-de-mar': 'Malgrat de Mar, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en la desembocadura del río Tordera, el municipio se asienta sobre depósitos aluviales y formaciones graníticas que favorecen la emanación de radón. Su carácter turístico, con campings y establecimientos hoteleros, hace relevante la verificación de niveles.\n\nACM-2020 ofrece servicios de medición de radón en Malgrat de Mar, con atención a establecimientos turísticos y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nMalgrat de Mar limita con [Palafolls](/municipios/palafolls), [Santa Susanna](/municipios/santa-susanna) y [Blanes](/municipios/blanes), todos ellos zonas de actuación prioritaria.',

  'sant-vicenc-de-montalt': 'Sant Vicenç de Montalt, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en las estribaciones de la Serralada Litoral, sobre formaciones graníticas paleozoicas del macizo de la Marina. El predominio de viviendas unifamiliares y urbanizaciones en las laderas incrementa el contacto con el sustrato granítico y la exposición potencial al radón.\n\nACM-2020 realiza mediciones de radón en Sant Vicenç de Montalt, con especial atención a urbanizaciones y viviendas en contacto directo con el terreno. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Vicenç de Montalt limita con [Caldes d\'Estrac](/municipios/caldes-d-estrac), [Arenys de Munt](/municipios/arenys-de-munt), [Arenys de Mar](/municipios/arenys-de-mar), [Sant Andreu de Llavaneres](/municipios/sant-andreu-de-llavaneres) y [Dosrius](/municipios/dosrius), todos ellos zonas de actuación prioritaria.',

  'premia-de-dalt': 'Premià de Dalt, en la comarca del Maresme, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, en una posición elevada respecto a la franja costera. Los sustratos paleozoicos y la orografía del municipio generan condiciones favorables para la emanación de radón, especialmente en las zonas altas.\n\nACM-2020 ofrece servicios de medición de radón en Premià de Dalt, con atención a viviendas unifamiliares y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nPremià de Dalt limita con [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Teià](/municipios/teia) y [Vallromanes](/municipios/vallromanes), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado, [Vilassar de Mar](/municipios/vilassar-de-mar) y [Premià de Mar](/municipios/premia-de-mar) (Zona 1).',

  'el-masnou': 'El Masnou, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Situado en la franja costera del Maresme, el municipio se asienta sobre la transición entre los depósitos litorales y las formaciones graníticas de la Serralada Litoral. Su núcleo urbano denso y el puerto deportivo se encuentran próximos a sustratos que pueden favorecer la emanación de radón.\n\nACM-2020 realiza mediciones de radón en el Masnou, con atención a edificios residenciales y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nEl Masnou limita con [Montgat](/municipios/montgat), [Teià](/municipios/teia), [Alella](/municipios/alella) (zonas de actuación prioritaria) y [Premià de Mar](/municipios/premia-de-mar) (Zona 1).',

  'sant-pol-de-mar': 'Sant Pol de Mar, en la comarca del Maresme, está clasificado en Zona II (exposición alta) al gas radón. Este municipio costero se sitúa entre el litoral y las estribaciones del macizo del Montnegre-Corredor, sobre formaciones graníticas que favorecen la emanación de radón. El núcleo histórico y las viviendas del municipio requieren verificación de niveles.\n\nACM-2020 ofrece servicios de medición de radón en Sant Pol de Mar, proporcionando informes técnicos para viviendas y centros de trabajo. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nSant Pol de Mar limita con [Sant Cebrià de Vallalta](/municipios/sant-cebria-de-vallalta), [Calella](/municipios/calella) y [Canet de Mar](/municipios/canet-de-mar), todos ellos zonas de actuación prioritaria.',

  // === VALLES ORIENTAL (new municipalities) ===
  'vallromanes': 'Vallromanes, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la vertiente interior de la Serralada Litoral, sobre formaciones graníticas paleozoicas que generan niveles elevados de radón. Su carácter residencial, con predominio de viviendas unifamiliares y fincas agrícolas, incrementa el contacto con el terreno y la exposición potencial.\n\nACM-2020 realiza mediciones de radón en Vallromanes, con especial atención a viviendas unifamiliares y masias del municipio. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nVallromanes limita con [Vilanova del Vallès](/municipios/vilanova-del-valles), [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Premià de Dalt](/municipios/premia-de-dalt), [Teià](/municipios/teia), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), [Montornès del Vallès](/municipios/montornes-del-valles) y [Alella](/municipios/alella), todos ellos municipios considerados zonas de actuación prioritaria.',

  'figaro-montmany': 'Figaró-Montmany, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en el congost del río Congost, paso natural entre el Vallès y la Plana de Vic, sobre formaciones graníticas y metamórficas que generan niveles elevados de radón. La orografía encajonada del valle y la geología del sustrato favorecen la concentración del gas.\n\nACM-2020 ofrece servicios de medición de radón en Figaró-Montmany, con experiencia en municipios del congost donde la geología granítica y las condiciones orográficas generan niveles significativos. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nFigaró-Montmany limita con [La Garriga](/municipios/la-garriga), [L\'Ametlla del Vallès](/municipios/ametlla-del-valles) y [Bigues i Riells](/municipios/bigues-i-riells), todos ellos zonas de actuación prioritaria, y por otro lado, Sant Marti de Centelles (Zona 1), y también limita con Tagamanent y Sant Quirze Safaja, zona sin clasificar.',

  'montornes-del-valles': 'Montornès del Vallès, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión vallesana y la Serralada Litoral, sobre formaciones graníticas y metamórficas que favorecen la emanación de radón. La combinación de zonas residenciales e industriales hace necesaria la verificación de niveles en diversos tipos de edificaciones.\n\nACM-2020 realiza mediciones de radón en Montornès del Vallès, con atención a centros de trabajo, polígonos industriales y viviendas del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nMontornès del Vallès limita con [Vilanova del Vallès](/municipios/vilanova-del-valles), [Vallromanes](/municipios/vallromanes), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), [Martorelles](/municipios/martorelles), todos ellos zonas de actuación prioritaria, y por otro lado [Granollers](/municipios/granollers) y Montmeló, que son Zona 1.',

  'sant-fost-de-campsentelles': 'Sant Fost de Campsentelles, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en las estribaciones de la Serra de Marina, sobre formaciones graníticas y metamórficas de la Serralada Litoral que generan niveles elevados de radón. Las urbanizaciones residenciales en las laderas de la sierra presentan mayor contacto con el sustrato granítico.\n\nACM-2020 ofrece servicios de medición de radón en Sant Fost de Campsentelles, con especial atención a viviendas unifamiliares y urbanizaciones del municipio. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nSant Fost de Campsentelles limita con [Tiana](/municipios/tiana), [Badalona](/municipios/badalona), [Montcada i Reixac](/municipios/montcada-i-reixac), [Martorelles](/municipios/martorelles), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), todos ellos zonas de actuación prioritaria, y por otro lado, La Llagosta y [Mollet del Vallès](/municipios/mollet-del-valles) (Zona 1).',

  'santa-eulalia-de-roncana': 'Santa Eulàlia de Ronçana, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en la vertiente sur de la Serralada Prelitoral, sobre formaciones graníticas que generan niveles elevados de radón. El carácter residencial del municipio, con viviendas unifamiliares y urbanizaciones dispersas, incrementa la superficie de contacto con el terreno.\n\nACM-2020 realiza mediciones de radón en Santa Eulàlia de Ronçana, proporcionando informes técnicos para viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nSanta Eulàlia de Ronçana limita con [Caldes de Montbui](/municipios/caldes-de-montbui), [Bigues i Riells](/municipios/bigues-i-riells) y [L\'Ametlla del Vallès](/municipios/ametlla-del-valles), todos ellos zonas de actuación prioritaria, y por otro lado, [Canovelles](/municipios/canovelles) y Lliçà d\'Amunt, municipios clasificados como Zona 1.',

  'gualba': 'Gualba, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado en la vertiente oriental del Montseny, el municipio se asienta sobre formaciones graníticas del macizo que generan niveles elevados de radón. La proximidad al Parc Natural del Montseny y la geología granítica del sustrato favorecen la emanación del gas.\n\nACM-2020 ofrece servicios de medición de radón en Gualba, con experiencia en municipios del entorno del Montseny donde la geología granítica genera condiciones muy favorables para la concentración de radón en interiores.\n\nGualba limita con [Sant Celoni](/municipios/sant-celoni) y Riells i Viabrea, todos ellos zonas de actuación prioritaria, y por otro lado, Campins (Zona 1).',

  'la-roca-del-valles': 'La Roca del Vallès, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión vallesana y la Serralada Litoral, sobre formaciones graníticas y metamórficas que favorecen la emanación de radón. Su importante actividad comercial, con centros de gran superficie, hace necesaria la verificación de niveles en centros de trabajo.\n\nACM-2020 realiza mediciones de radón en La Roca del Vallès, con atención a centros comerciales, polígonos industriales y viviendas del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nLa Roca del Vallès limita con [Llinars del Vallès](/municipios/llinars-del-valles), [Dosrius](/municipios/dosrius), [Argentona](/municipios/argentona), [Òrrius](/municipios/orrius), [Vilanova del Vallès](/municipios/vilanova-del-valles), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado, [Granollers](/municipios/granollers), [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles) i [Cardedeu](/municipios/cardedeu) (Zona 1).',

  'martorelles': 'Martorelles, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión vallesana y las estribaciones de la Serra de Marina, sobre formaciones graníticas que favorecen la emanación de radón. Su proximidad a polígonos industriales y centros logísticos hace necesaria la verificación de niveles en centros de trabajo.\n\nACM-2020 ofrece servicios de medición de radón en Martorelles, proporcionando informes técnicos para viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nMartorelles limita con [Montornès del Vallès](/municipios/montornes-del-valles), [Santa Maria de Martorelles](/municipios/santa-maria-de-martorelles), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles), todos ellos zonas de actuación prioritaria, y por otro lado [Mollet del Vallès](/municipios/mollet-del-valles) y Montmeló (Zona 1).',

  'vilalba-sasserra': 'Vilalba Sasserra, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Este pequeño municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, en la transición hacia el macizo del Montnegre-Corredor. Su reducido tamaño y carácter rural, con viviendas dispersas sobre terreno granítico, genera condiciones favorables para la infiltración de radón.\n\nACM-2020 realiza mediciones de radón en Vilalba Sasserra, con experiencia en municipios del interior del Vallès Oriental donde la geología granítica genera niveles elevados. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nVilalba Sasserra limita con [Llinars del Vallès](/municipios/llinars-del-valles), [Vallgorguina](/municipios/vallgorguina) y [Dosrius](/municipios/dosrius), todos ellos zonas de actuación prioritaria.',

  'vallgorguina': 'Vallgorguina, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado en la vertiente interior del macizo del Montnegre-Corredor, el municipio se asienta sobre formaciones graníticas paleozoicas que generan niveles elevados de radón. El entorno boscoso y montañoso del municipio evidencia la geología antigua del sustrato.\n\nACM-2020 ofrece servicios de medición de radón en Vallgorguina, con atención a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nVallgorguina limita con [Sant Celoni](/municipios/sant-celoni), [Sant Iscle de Vallalta](/municipios/sant-iscle-de-vallalta), [Arenys de Munt](/municipios/arenys-de-munt), [Dosrius](/municipios/dosrius), [Vilalba Sasserra](/municipios/vilalba-sasserra) y [Santa Maria de Palautordera](/municipios/santa-maria-de-palautordera), todos ellos zonas de actuación prioritaria.',

  'santa-maria-de-palautordera': 'Santa Maria de Palautordera, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Situado al pie del Montseny, el municipio se asienta sobre formaciones graníticas del macizo que generan niveles elevados de radón. La proximidad al Parc Natural del Montseny y los torrentes que descienden del macizo evidencian la fracturación del sustrato granítico.\n\nACM-2020 realiza mediciones de radón en Santa Maria de Palautordera, con experiencia en municipios del entorno del Montseny. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSanta Maria de Palautordera limita con [Sant Celoni](/municipios/sant-celoni), [Vallgorguina](/municipios/vallgorguina) y [Llinars del Vallès](/municipios/llinars-del-valles), todos ellos zonas de actuación prioritaria, y por otro lado con Sant Esteve de Palautordera, Fogars de Montclus (ambos zona 1).',

  'ametlla-del-valles': 'L\'Ametlla del Vallès, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. El municipio se sitúa en la vertiente sur de la Serralada Prelitoral, sobre formaciones graníticas que generan niveles elevados de radón. Su carácter residencial disperso, con numerosas urbanizaciones y viviendas aisladas entre bosques, incrementa la exposición potencial al gas.\n\nACM-2020 ofrece servicios de medición de radón en L\'Ametlla del Vallès, con especial atención a urbanizaciones y viviendas unifamiliares donde el contacto directo con el terreno granítico favorece la infiltración. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nL\'Ametlla del Vallès limita con [Bigues i Riells](/municipios/bigues-i-riells), [Santa Eulàlia de Ronçana](/municipios/santa-eulalia-de-roncana), [Figaró-Montmany](/municipios/figaro-montmany) y [La Garriga](/municipios/la-garriga), todos ellos municipios en zonas de actuación prioritaria, y por otro lado, [Les Franqueses del Vallès](/municipios/les-franqueses-del-valles) y [Canovelles](/municipios/canovelles), municipios clasificados como Zona 1.',

  'vilanova-del-valles': 'Vilanova del Vallès, en la comarca del Vallès Oriental, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa sobre formaciones graníticas de la Serralada Litoral, en la transición entre la depresión vallesana y el macizo de la Marina. Los sustratos paleozoicos del municipio generan condiciones favorables para la emanación de radón.\n\nACM-2020 realiza mediciones de radón en Vilanova del Vallès, con atención a viviendas y centros de trabajo del municipio. La medición es obligatoria en esta zona de actuación prioritaria según el RD 1029/2022.\n\nVilanova del Vallès limita con [La Roca del Vallès](/municipios/la-roca-del-valles), [Òrrius](/municipios/orrius), [Vilassar de Dalt](/municipios/vilassar-de-dalt), [Vallromanes](/municipios/vallromanes), [Montornès del Vallès](/municipios/montornes-del-valles), todos ellos municipios considerados zonas de actuación prioritaria, y por otro lado, [Granollers](/municipios/granollers) (Zona 1).',

  'santa-maria-de-martorelles': 'Santa Maria de Martorelles, en la comarca del Vallès Oriental, está clasificada en Zona II (exposición alta) al gas radón. Este pequeño municipio se sitúa sobre las formaciones graníticas de la Serra de Marina, entre la depresión vallesana y la Serralada Litoral. Los sustratos paleozoicos y la posición orográfica del municipio favorecen la emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Santa Maria de Martorelles, proporcionando informes técnicos para viviendas y centros de trabajo. La medición es obligatoria en esta zona de actuación prioritaria conforme al RD 1029/2022.\n\nSanta Maria de Martorelles limita con [Martorelles](/municipios/martorelles), [Montornès del Vallès](/municipios/montornes-del-valles), [Tiana](/municipios/tiana), [Sant Fost de Campsentelles](/municipios/sant-fost-de-campsentelles), [Vallromanes](/municipios/vallromanes) y [Alella](/municipios/alella), todos ellos zonas de actuación prioritaria.',

  // === OSONA (new municipalities) ===
  'sant-sadurni-d-osormort': 'Sant Sadurní d\'Osormort, en la comarca de Osona, está clasificado en Zona II (exposición alta) al gas radón. Este municipio rural de les Guilleries se asienta sobre formaciones graníticas paleozoicas del macizo, una de las formaciones graníticas más extensas de Catalunya. La baja densidad de población y el carácter disperso de las masias generan edificaciones con alto contacto con el terreno granítico.\n\nACM-2020 realiza mediciones de radón en Sant Sadurní d\'Osormort, con experiencia en municipios de les Guilleries donde la geología granítica genera niveles muy elevados. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nSant Sadurní d\'Osormort limita con Viladrau, Espinelves, [Vilanova de Sau](/municipios/vilanova-de-sau), todos ellos zonas de actuación prioritaria, y por otro lado, Folgueroles y Tavernoles (Zona 1).',

  'vilanova-de-sau': 'Vilanova de Sau, en la comarca de Osona, está clasificada en Zona II (exposición alta) al gas radón. Situada en el corazón de les Guilleries, junto al pantano de Sau, el municipio se asienta sobre formaciones graníticas paleozoicas que generan niveles muy elevados de radón. El entorno montañoso y boscoso del municipio, con masias dispersas, presenta condiciones geológicas muy favorables para la emanación.\n\nACM-2020 ofrece servicios de medición de radón en Vilanova de Sau, con atención a masias y viviendas del municipio donde el contacto con el sustrato granítico es directo. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nVilanova de Sau limita con [Sant Sadurní d\'Osormort](/municipios/sant-sadurni-d-osormort), Sant Hilari Sacalm y Espinelves, todos ellos zonas de actuación prioritaria, y por otro lado, Les Masies de Roda i Tavernoles (Zona 1), y Tavertet, Rupit i Pruit, municipios sin clasificar.',

  // === BERGUEDA (new municipalities) ===
  'castellar-de-n-hug': 'Castellar de n\'Hug, en la comarca del Berguedà, está clasificado en Zona II (exposición alta) al gas radón. Este municipio pirenaico, situado a más de 1.300 metros de altitud junto a las fuentes del Llobregat, se asienta sobre formaciones graníticas y metamórficas que generan niveles muy elevados de radón. El clima frío de alta montaña, con largos inviernos y ventilación reducida, agrava la concentración del gas en interiores.\n\nACM-2020 realiza mediciones de radón en Castellar de n\'Hug, con experiencia en edificaciones de alta montaña del Berguedà. La medición es obligatoria en centros de trabajo según el RD 1029/2022.\n\nCastellar de n\'Hug limita con [Guardiola de Berguedà](/municipios/guardiola-de-bergueda), [Bagà](/municipios/baga), [Alp](/municipios/alp), Toses, todos ellos zonas de actuación prioritaria, y por otro lado, [la Pobla de Lillet](/municipios/la-pobla-de-lillet) y [Gombren](/municipios/sant-joan-de-les-abadesses-2), municipios en Zona 1.',

  // === SELVA (new municipalities) ===
  'fogars-de-la-selva': 'Fogars de la Selva, en la comarca de la Selva, está clasificado en Zona II (exposición alta) al gas radón. El municipio se sitúa en la transición entre la depresión prelitoral y las estribaciones del macizo del Montnegre, sobre formaciones graníticas que generan niveles elevados de radón. La geología granítica de la comarca de la Selva es una de las más relevantes de Catalunya en cuanto a emanación de radón.\n\nACM-2020 ofrece servicios de medición de radón en Fogars de la Selva, con experiencia en municipios de la Selva donde la geología granítica genera condiciones muy favorables para la concentración de radón. La medición es obligatoria en centros de trabajo conforme al RD 1029/2022.\n\nFogars de la Selva limita con Macanet de la Selva, [Sant Celoni](/municipios/sant-celoni), Sant Feliu de Buixalleu, [Tordera](/municipios/tordera) y [Hostalric](/municipios/hostalric), todos ellos zonas de actuación prioritaria.',
}

export function getMunicipioContent(slug: string): string | undefined {
  return municipiosContent[slug]
}
